import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  poweredByHeader: false,
  images: {
    localPatterns: [{ pathname: "/uploads/**" }],
    remotePatterns: [{ protocol: "https", hostname: "*.public.blob.vercel-storage.com" }],
  },
  async headers() {
    return [
      {
        source: "/admin/:path*",
        headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow" }],
      },
      {
        source: "/api/admin/:path*",
        headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow" }],
      },
    ];
  },
};

export default nextConfig;

import { defineConfig } from "drizzle-kit";

try {
  process.loadEnvFile(".env");
} catch {
  // no .env file: rely on the real environment
}

export default defineConfig({
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dialect: "postgresql",
  dbCredentials: { url: process.env.DATABASE_URL ?? "" },
});

import {
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  serial,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

export type NavItem = { label: string; target: string; style?: "button" };

export const site = pgTable("site", {
  id: integer("id").primaryKey().default(1),
  name: text("name").notNull(),
  tagline: text("tagline").notNull().default(""),
  description: text("description").notNull().default(""),
  contactEmail: text("contact_email").notNull().default(""),
  accent: text("accent").notNull().default("#3f6f73"),
  demoNotice: boolean("demo_notice").notNull().default(false),
  successTargetSignups: integer("success_target_signups"),
  successTargetDays: integer("success_target_days"),
  launchedAt: timestamp("launched_at", { withTimezone: true }).notNull().defaultNow(),
  nav: jsonb("nav").$type<NavItem[]>().notNull().default([]),
});

export const blocks = pgTable("blocks", {
  id: text("id").primaryKey(),
  type: text("type").notNull(),
  position: integer("position").notNull(),
  visible: boolean("visible").notNull().default(true),
  content: jsonb("content").$type<Record<string, unknown>>().notNull().default({}),
});

export const formFields = pgTable("form_fields", {
  key: text("key").primaryKey(),
  label: text("label").notNull(),
  type: text("type").notNull(),
  required: boolean("required").notNull().default(false),
  options: jsonb("options").$type<string[]>().notNull().default([]),
  position: integer("position").notNull(),
});

export const signups = pgTable(
  "signups",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    email: text("email").notNull().unique(),
    answers: jsonb("answers").$type<Record<string, string | string[]>>().notNull().default({}),
    source: text("source").notNull().default("direct"),
    isSample: boolean("is_sample").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("signups_created_idx").on(t.createdAt)],
);

export const images = pgTable("images", {
  id: uuid("id").primaryKey().defaultRandom(),
  url: text("url").notNull(),
  alt: text("alt").notNull(),
  width: integer("width").notNull(),
  height: integer("height").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const rateEvents = pgTable(
  "rate_events",
  {
    id: serial("id").primaryKey(),
    scope: text("scope").notNull(),
    key: text("key").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("rate_events_lookup_idx").on(t.scope, t.key, t.createdAt)],
