import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
import * as schema from "./schema";

const globalForDb = globalThis as unknown as { __pgPool?: Pool };

function getPool(): Pool {
  if (!globalForDb.__pgPool) {
    globalForDb.__pgPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      max: 5,
      connectionTimeoutMillis: 5000,
    });
    globalForDb.__pgPool.on("error", (err) => console.error("Postgres pool error:", err.message));
  }
  return globalForDb.__pgPool;
}

export const db = drizzle(getPool(), { schema });
export { schema };

import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

const KEY_LENGTH = 64;

/** Returns "scrypt:<salt hex>:<hash hex>". */
export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, KEY_LENGTH).toString("hex");
  return `scrypt:${salt}:${hash}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const parts = stored.split(":");
  if (parts.length !== 3 || parts[0] !== "scrypt") return false;
  const [, salt, hashHex] = parts;
  if (!salt || !/^[0-9a-f]+$/i.test(hashHex) || hashHex.length % 2 !== 0) return false;
  const expected = Buffer.from(hashHex, "hex");
  const actual = scryptSync(password, salt, expected.length);
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}

import { hashPassword } from "../src/lib/password";

const password = process.argv[2];
if (!password) {
  console.error("Usage: npm run hash-password -- <password>");
  process.exit(1);
}
process.stdout.write(hashPassword(password) + "\n");

export const REQUIRED_ENV = [
  "DATABASE_URL",
  "ADMIN_EMAIL",
  "ADMIN_PASSWORD_HASH",
  "SESSION_SECRET",
] as const;

export function missingEnv(env: Record<string, string | undefined>): string[] {
  return REQUIRED_ENV.filter((name) => !env[name] || env[name]!.trim() === "");
}

export function envProblemMessage(env: Record<string, string | undefined>): string | null {
  const missing = missingEnv(env);
  if (missing.length === 0) {
    if ((env.SESSION_SECRET ?? "").length < 16) {
      return "SESSION_SECRET is too short: use at least 16 characters.";
    }
    return null;
  }
  return `Cannot start: missing setting${missing.length > 1 ? "s" : ""} ${missing.join(", ")}. Set ${
    missing.length > 1 ? "them" : "it"
  } in the environment (see .env.example).`;
}

export async function register() {
  if (process.env.NEXT_RUNTIME !== "nodejs") return;
  const { envProblemMessage } = await import("./lib/env");
  const problem = envProblemMessage(process.env);
  if (problem) {
    console.error(`\n${problem}\n`);
    throw new Error(problem);
  }
}

import "server-only";
import { createHmac, timingSafeEqual } from "node:crypto";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";

export const SESSION_COOKIE = "owner_session";
const SESSION_SECONDS = 60 * 60 * 24 * 7;

function sign(payload: string): string {
  return createHmac("sha256", process.env.SESSION_SECRET ?? "").update(payload).digest("base64url");
}

export function createSessionToken(email: string): string {
  const payload = Buffer.from(
    JSON.stringify({ email, exp: Math.floor(Date.now() / 1000) + SESSION_SECONDS }),
  ).toString("base64url");
  return `${payload}.${sign(payload)}`;
}

export function verifySessionToken(token: string | undefined): boolean {
  if (!token || !process.env.SESSION_SECRET || !process.env.ADMIN_EMAIL) return false;
  const [payload, signature] = token.split(".");
  if (!payload || !signature) return false;
  const expected = sign(payload);
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return false;
  try {
    const data = JSON.parse(Buffer.from(payload, "base64url").toString("utf8")) as {
      email?: string;
      exp?: number;
    };
    return (
      typeof data.exp === "number" &&
      data.exp > Date.now() / 1000 &&
      data.email === process.env.ADMIN_EMAIL.trim().toLowerCase()
    );
  } catch {
    return false;
  }
}

export async function isOwner(): Promise<boolean> {
  const store = await cookies();
  return verifySessionToken(store.get(SESSION_COOKIE)?.value);
}

/** For pages and server actions: redirect to sign-in without a session. */
export async function requireOwner(): Promise<void> {
  if (!(await isOwner())) redirect("/admin/sign-in");
}

export async function startSession(email: string) {
  const store = await cookies();
  store.set(SESSION_COOKIE, createSessionToken(email), {
    httpOnly: true,
    sameSite: "lax",
    secure: !!process.env.VERCEL,
    path: "/",
    maxAge: SESSION_SECONDS,
  });
}

export async function endSession() {
  const store = await cookies();
  store.delete(SESSION_COOKIE);
}

