import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
import { blocks, formFields, signups, site } from "../src/db/schema";
import {
  SEED_BLOCKS,
  SEED_FIELDS,
  SEED_NAV,
  SEED_SAMPLES,
  SEED_SITE,
} from "../src/lib/seed-data";

try {
  process.loadEnvFile(".env");
} catch {
  // no .env file: rely on the real environment
}

async function main() {
  if (!process.env.DATABASE_URL) {
    console.error("DATABASE_URL is not set.");
    process.exit(1);
  }
  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
  const db = drizzle(pool);

  const existing = await db.select({ id: site.id }).from(site).limit(1);
  if (existing.length > 0) {
    console.log("Site row already exists: nothing seeded.");
    await pool.end();
    return;
  }

  await db.transaction(async (tx) => {
    await tx.insert(site).values({ ...SEED_SITE, nav: SEED_NAV, launchedAt: new Date() });
    await tx.insert(blocks).values(
      SEED_BLOCKS.map((b, i) => ({ id: b.id, type: b.type, position: i, visible: true, content: b.content })),
    );
    await tx.insert(formFields).values(SEED_FIELDS);
    await tx.insert(signups).values(
      SEED_SAMPLES.map((s, i) => ({
        email: s.email,
        answers: { full_name: s.name },
        source: s.source,
        isSample: true,
        createdAt: new Date(Date.now() - (i + 1) * 3_600_000),
      })),
    );
  });
  console.log("Seeded the site, blocks, form fields and sample signups (labelled as samples).");
  await pool.end();
}

main().catch((err) => {
  console.error("Seed failed:", err instanceof Error ? err.message : err);
  process.exit(1);
});

import { userInfo } from "node:os";
import type { PoolConfig } from "pg";

/**
 * Pool options from DATABASE_URL. A local connection string may have no user name
 * (trust authentication); then fall back to PGUSER, USER or the operating system user.
 */
export function connectionOptions(url = process.env.DATABASE_URL): PoolConfig {
  const config: PoolConfig = { connectionString: url };
  let hasUser = false;
  try {
    hasUser = !!url && new URL(url).username !== "";
  } catch {
    hasUser = true; // unparsable: let pg report the problem
  }
  if (!hasUser && !process.env.PGUSER && !process.env.USER) {
    try {
      config.user = userInfo().username;
    } catch {
      // leave unset
    }
  }
  return config;
}

