import { userInfo } from "node:os";
import type { PoolConfig } from "pg";

/**
 * Pool options from DATABASE_URL. A local connection string may have no user name
 * (trust authentication); then use PGUSER, USER or the operating system user,
 * because pg gives up when none of them is set.
 */
export function connectionOptions(url = process.env.DATABASE_URL): PoolConfig {
  if (!url) return { connectionString: url };
  try {
    const parsed = new URL(url);
    if (parsed.username === "") {
      const user = process.env.PGUSER || process.env.USER || userInfo().username;
      if (user) parsed.username = encodeURIComponent(user);
    }
    return { connectionString: parsed.toString() };
  } catch {
    return { connectionString: url };
  }
}

import "server-only";
import { asc, eq, inArray } from "drizzle-orm";
import { db } from "@/db";
import { blocks, formFields, images, site } from "@/db/schema";
import { BLOCK_IDS, BLOCK_SCHEMAS, type BlockId, type FieldRow } from "@/lib/content";
import { SEED_BLOCKS } from "@/lib/seed-data";

export type SiteRow = typeof site.$inferSelect;
export type ImageRow = typeof images.$inferSelect;

export async function getSite(): Promise<SiteRow | null> {
  const rows = await db.select().from(site).where(eq(site.id, 1)).limit(1);
  return rows[0] ?? null;
}

export async function getFields(): Promise<FieldRow[]> {
  const rows = await db.select().from(formFields).orderBy(asc(formFields.position));
  return rows.map((r) => ({ ...r, options: Array.isArray(r.options) ? r.options : [] }));
}

export type LoadedBlock = {
  id: BlockId;
  position: number;
  visible: boolean;
  // Validated content for this block type (falls back to the starting content if the stored JSON is invalid).
  content: Record<string, unknown>;
};

function isBlockId(id: string): id is BlockId {
  return (BLOCK_IDS as readonly string[]).includes(id);
}

export async function getBlocks(): Promise<LoadedBlock[]> {
  const rows = await db.select().from(blocks).orderBy(asc(blocks.position));
  const out: LoadedBlock[] = [];
  for (const r of rows) {
    if (!isBlockId(r.id)) continue;
    const parsed = BLOCK_SCHEMAS[r.id].safeParse(r.content);
    const fallback = SEED_BLOCKS.find((b) => b.id === r.id)?.content ?? {};
    out.push({
      id: r.id,
      position: r.position,
      visible: r.visible,
      content: (parsed.success ? parsed.data : BLOCK_SCHEMAS[r.id].parse(fallback)) as Record<string, unknown>,
    });
  }
  return out;
}

export async function getImagesByIds(ids: (string | null | undefined)[]): Promise<Map<string, ImageRow>> {
  const clean = ids.filter((x): x is string => !!x);
  if (clean.length === 0) return new Map();
  const rows = await db.select().from(images).where(inArray(images.id, clean));
  return new Map(rows.map((r) => [r.id, r]));
}

export async function getImage(id: string | null | undefined): Promise<ImageRow | null> {
  if (!id) return null;
  return (await getImagesByIds([id])).get(id) ?? null;
}

