  --accent-soft: color-mix(in srgb, var(--accent) 10%, var(--surface));
  --danger: #b42318;
  --danger-soft: #fef3f2;
  --success: #1a6b3c;
  --success-soft: #edf8f1;
  --radius: 12px;
  --notice-h: 40px;
  --header-h: 72px;
}

@theme inline {
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-border: var(--border);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent-soft: var(--accent-soft);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --color-success: var(--success);
  --color-success-soft: var(--success-soft);
  --font-sans: var(--font-dm-sans), ui-sans-serif, system-ui, sans-serif;
  --font-heading: var(--font-fraunces), ui-serif, Georgia, serif;
  --radius-card: var(--radius);
}

html {
  background: var(--background);
  color: var(--foreground);
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 17px;
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

@media (min-width: 768px) {
  body {
    font-size: 18px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
  .rise {
    animation: rise 0.6s ease-out both;
  }
  @keyframes rise {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* One section rhythm for every block: 56px on a phone, 96px on desktop. */
.section {
  padding-block: 56px;
}
@media (min-width: 768px) {
  .section {
    padding-block: 96px;
  }
}

.container-page {
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: 20px;
}
@media (min-width: 768px) {
  .container-page {
    padding-inline: 32px;
  }
}

.font-heading {
  font-family: var(--font-heading);
}

.heading-hero {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 38px;
  line-height: 1.08;
  letter-spacing: -0.01em;
  text-wrap: balance;
}
@media (min-width: 768px) {
  .heading-hero {
    font-size: 60px;
  }
}

.heading-section {
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 28px;
  line-height: 1.15;
  text-wrap: balance;
}
@media (min-width: 768px) {
  .heading-section {
    font-size: 38px;
  }
}

/* Anchors land below the sticky header. */
section[id],
footer[id] {
  scroll-margin-top: var(--header-h);
}

/* Honeypot: off-screen, not display:none, so bots still see it. */
.hp-field {
  position: absolute;
  left: -10000px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}

