// Hidden spam trap. The name is random (hp_ plus six letters/digits), chosen once for this site.
// It is deliberately not a word that browsers or password managers autofill.
export const HP_FIELD = "hp_4fz9kd";

"use client";

import Image from "next/image";
import { useState } from "react";

/** next/image with set dimensions; shows the given placeholder if the file fails to load. */
export function SafeImage({
  src,
  alt,
  width,
  height,
  sizes,
  priority,
  className,
  fallback,
}: {
  src: string;
  alt: string;
  width: number;
  height: number;
  sizes?: string;
  priority?: boolean;
  className?: string;
  fallback: React.ReactNode;
}) {
  const [failed, setFailed] = useState(false);
  if (failed) return <>{fallback}</>;
  return (
    <Image
      src={src}
      alt={alt}
      width={width}
      height={height}
      sizes={sizes}
      priority={priority}
      className={className}
      style={{ width: "100%", height: "auto" }}
      onError={() => setFailed(true)}
    />
  );
}

// Small decorative SVG shapes in the accent and the neutrals. They carry no words.

export function RingIllustration({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 240 240" aria-hidden="true" focusable="false" className={className} fill="none">
      <circle cx="120" cy="120" r="104" stroke="var(--border)" strokeWidth="1" />
      <circle cx="120" cy="120" r="80" stroke="var(--accent)" strokeOpacity="0.25" strokeWidth="1" />
      <circle cx="120" cy="120" r="64" stroke="var(--accent)" strokeWidth="14" />
      <circle cx="120" cy="120" r="50" stroke="var(--accent)" strokeOpacity="0.35" strokeWidth="2" />
      <path d="M62 52a104 104 0 0 1 60-20" stroke="var(--accent)" strokeOpacity="0.4" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

export function WavePattern({ variant }: { variant: number }) {
  const v = variant % 3;
  return (
    <svg viewBox="0 0 400 300" aria-hidden="true" focusable="false" className="h-full w-full" preserveAspectRatio="xMidYMid slice" fill="none">
      {v === 0 && (
        <>
          <circle cx="280" cy="110" r="70" fill="var(--accent)" fillOpacity="0.12" />
          <path d="M0 200 C60 170 120 230 200 200 S340 170 400 200 V300 H0 Z" fill="var(--accent)" fillOpacity="0.2" />
          <path d="M0 240 C80 210 140 270 220 240 S350 215 400 240 V300 H0 Z" fill="var(--accent)" fillOpacity="0.3" />
        </>
      )}
      {v === 1 && (
        <>
          <circle cx="120" cy="120" r="90" stroke="var(--accent)" strokeOpacity="0.25" />
          <circle cx="120" cy="120" r="60" stroke="var(--accent)" strokeOpacity="0.35" />
          <circle cx="120" cy="120" r="30" fill="var(--accent)" fillOpacity="0.25" />
          <path d="M200 220 C260 190 320 250 400 215" stroke="var(--accent)" strokeOpacity="0.4" strokeWidth="2" />
        </>
      )}
      {v === 2 && (
        <>
          {Array.from({ length: 6 }).map((_, i) => (
            <path
              key={i}
              d={`M0 ${90 + i * 28} C80 ${60 + i * 28} 140 ${120 + i * 28} 220 ${90 + i * 28} S340 ${70 + i * 28} 400 ${90 + i * 28}`}
              stroke="var(--accent)"
              strokeOpacity={0.15 + i * 0.06}
              strokeWidth="2"
            />
          ))}
        </>
      )}
    </svg>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Menu, X } from "lucide-react";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export type HeaderLink = { label: string; href: string; button?: boolean };

export function SiteHeader({ name, links }: { name: string; links: HeaderLink[] }) {
  const [open, setOpen] = useState(false);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const plain = links.filter((l) => !l.button);
  const cta = links.find((l) => l.button);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        toggleRef.current?.focus();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);

  return (
    <header
      className="sticky top-0 z-40 border-b border-border bg-background/95 backdrop-blur"
      style={{ height: "var(--header-h)" }}
    >
      <div className="container-page flex h-full items-center justify-between gap-4">
        <a href="#hero" className="font-heading text-xl font-semibold tracking-tight">
          {name}
        </a>

        <nav aria-label="Main" className="hidden items-center gap-8 md:flex">
          {plain.map((l) => (
            <a key={l.href + l.label} href={l.href} className="text-base text-muted hover:text-foreground">
              {l.label}
            </a>
          ))}
          {cta && (
            <a href={cta.href} className={buttonVariants({ variant: "primary" })}>
              {cta.label}
            </a>
          )}
        </nav>

        {links.length > 0 && (
          <button
            ref={toggleRef}
            type="button"
            className="inline-flex size-11 items-center justify-center rounded-[var(--radius)] border border-border bg-surface md:hidden"
            aria-expanded={open}
            aria-controls="mobile-menu"
            aria-label={open ? "Close menu" : "Open menu"}
            onClick={() => setOpen((v) => !v)}
          >
            {open ? <X size={20} strokeWidth={1.75} aria-hidden="true" /> : <Menu size={20} strokeWidth={1.75} aria-hidden="true" />}
          </button>
        )}
      </div>

      {open && (
        <nav
          id="mobile-menu"
          aria-label="Mobile"
          className="absolute inset-x-0 top-full border-b border-border bg-background md:hidden"
        >
          <ul className="container-page flex flex-col gap-1 py-4">
            {plain.map((l) => (
              <li key={l.href + l.label}>
                <a
                  href={l.href}
                  onClick={() => setOpen(false)}
                  className="flex min-h-11 items-center text-base text-foreground"
                >
                  {l.label}
                </a>
              </li>
            ))}
            {cta && (
              <li className="pt-2">
                <a
                  href={cta.href}
                  onClick={() => setOpen(false)}
                  className={cn(buttonVariants({ variant: "primary" }), "w-full")}
                >
                  {cta.label}
                </a>
              </li>
            )}
          </ul>
        </nav>
      )}
    </header>
  );
}

