export function Hero({
  content,
  image,
  background,
  demoNotice,
}: {
  content: HeroContent;
  image: ImageRow | null;
  background: ImageRow | null;
  demoNotice: boolean;
}) {
  // With a background photo the text sits on a dimming layer. "none" is raised to "soft"
  // so text always keeps a contrast of 4.5:1 or more.
  const hasBg = !!background && background.alt.trim() !== "";
  const overlay = content.dimming === "strong" ? "bg-black/70" : "bg-black/55";
  const shownImage = image && image.alt.trim() !== "" ? image : null;

  return (
    <section
      id="hero"
      aria-labelledby="hero-heading"
      className="relative isolate flex items-center overflow-hidden"
      style={{
        minHeight: `calc(100svh - var(--header-h)${demoNotice ? " - var(--notice-h)" : ""})`,
        background: hasBg
          ? undefined
          : "radial-gradient(ellipse 70% 80% at 85% 10%, var(--accent-soft), transparent 70%), radial-gradient(ellipse 50% 60% at 0% 100%, color-mix(in srgb, var(--accent) 6%, var(--background)), transparent 70%), var(--background)",
      }}
    >
      {hasBg && background && (
        <>
          <Image
            src={background.url}
            alt=""
            fill
            priority
            sizes="100vw"
            className="-z-20 object-cover"
          />
          <div className={cn("absolute inset-0 -z-10", overlay)} aria-hidden="true" />
        </>
      )}
      <div className="container-page grid w-full items-center gap-8 py-10 md:grid-cols-2 md:gap-16 md:py-16">
        <div className={cn("rise max-w-[720px]", hasBg && "text-white")}>
          <h1 id="hero-heading" className="heading-hero">
            {content.headline}
          </h1>
          {content.subheadline && (
            <p className={cn("mt-4 max-w-prose md:mt-6", hasBg ? "text-white" : "text-muted")}>{content.subheadline}</p>
          )}
          <div className="mt-6 flex flex-col items-start gap-3 md:mt-8">
            <a href="#waitlist" className={cn(buttonVariants({ variant: "primary" }), hasBg && "ring-2 ring-white/70")}>
              {content.ctaLabel}
            </a>
            {content.note && <p className={cn("text-sm", hasBg ? "text-white" : "text-muted")}>{content.note}</p>}
          </div>
        </div>
        <div className="rise">
          {shownImage ? (
            <SafeImage
              src={shownImage.url}
              alt={shownImage.alt}
              width={shownImage.width}
              height={shownImage.height}
              sizes="(min-width: 768px) 560px, 100vw"
              priority
              className="rounded-[var(--radius)] border border-border"
              fallback={<RingPlaceholder onDark={hasBg} />}
            />
          ) : (
            <RingPlaceholder onDark={hasBg} />
          )}
        </div>
      </div>
    </section>
  );
}

