    <section id="preview" aria-labelledby="preview-heading" className="section">
      <div className="container-page grid items-center gap-10 md:grid-cols-2 md:gap-16">
        <div>
          <h2 id="preview-heading" className="heading-section">
            {content.heading}
          </h2>
          {content.text && <p className="mt-4 max-w-prose text-muted md:mt-6">{content.text}</p>}
        </div>
        <div className="flex justify-center">
          {shown ? (
            <SafeImage
              src={shown.url}
              alt={shown.alt}
