  const items = content.items.filter((i) => !i.hidden && i.title.trim() !== "");
  if (items.length === 0) return null;
  return (
    <section id="benefits" aria-labelledby="benefits-heading" className="section border-t border-border bg-surface">
      <div className="container-page">
        <h2 id="benefits-heading" className="heading-section max-w-prose">
          {content.heading}
        </h2>
        <ul className="mt-10 flex flex-col gap-12 md:mt-16 md:gap-20">
          {items.map((item, i) => {
            const Icon = ICONS[i % ICONS.length];
            const flip = i % 2 === 1;
            return (
              <li
                key={i}
                data-benefit-row
                className="grid items-center gap-6 md:grid-cols-2 md:gap-16"
              >
                <div
                  data-benefit-art
                  aria-hidden="true"
                  className={cn(
                    "aspect-[4/3] overflow-hidden rounded-[var(--radius)] border border-border bg-accent-soft",
                    flip && "md:order-2",
                  )}
                >
                  <WavePattern variant={i} />
                </div>
                <div className={cn(flip && "md:order-1")}>
                  <h3 className="flex items-start gap-3 font-heading text-2xl font-medium">
                    <Icon size={24} strokeWidth={1.75} className="mt-1 shrink-0 text-accent" aria-hidden="true" />
                    <span>{item.title}</span>
                  </h3>
                  {item.text && <p className="mt-3 max-w-prose text-muted">{item.text}</p>}
                </div>
              </li>
