"use client";

import { useEffect, useRef, useState } from "react";
import { CheckCircle2, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input, Select } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { HP_FIELD } from "@/lib/honeypot";

type Field = { key: string; label: string; type: string; required: boolean; options: string[] };
type Values = Record<string, string | string[]>;

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SOURCE_KEY = "waitlist_source";

export function WaitlistForm({
  fields,
  submitLabel,
  successMessage,
  privacyNote,
}: {
  fields: Field[];
  submitLabel: string;
  successMessage: string;
  privacyNote: string;
}) {
  const [values, setValues] = useState<Values>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [formError, setFormError] = useState("");
  const [status, setStatus] = useState<"idle" | "sending" | "done">("idle");
  const [source, setSource] = useState("");
  const sending = useRef(false);
  const doneRef = useRef<HTMLDivElement>(null);
  const formRef = useRef<HTMLFormElement>(null);

  // Remember where the visitor came from for the whole visit: ?src= wins over utm_source.
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const fresh = params.get("src") ?? params.get("utm_source");
      if (fresh !== null && fresh.trim() !== "") sessionStorage.setItem(SOURCE_KEY, fresh);
      setSource(sessionStorage.getItem(SOURCE_KEY) ?? "");
    } catch {
      /* storage may be blocked: the signup is then recorded as direct */
    }
  }, []);

  useEffect(() => {
    if (status === "done") doneRef.current?.focus();
  }, [status]);

  const setValue = (key: string, value: string | string[]) => {
    setValues((v) => ({ ...v, [key]: value }));
    setErrors((e) => {
      if (!e[key]) return e;
      const next = { ...e };
      delete next[key];
      return next;
    });
  };

  const validate = (): Record<string, string> => {
    const out: Record<string, string> = {};
    for (const f of fields) {
      const v = values[f.key];
      const text = typeof v === "string" ? v.trim() : "";
      if (f.type === "email") {
        if (!EMAIL_RE.test(text)) out[f.key] = "Please enter a valid email address";
      } else if (f.required) {
        const empty = f.type === "multiselect" ? !Array.isArray(v) || v.length === 0 : text === "";
        if (empty) out[f.key] = `Please answer “${f.label}”`;
      }
    }
    return out;
  };

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (sending.current) return;
    setFormError("");
    const found = validate();
    setErrors(found);
    const firstBad = fields.find((f) => found[f.key]);
    if (firstBad) {
      formRef.current?.querySelector<HTMLElement>(`[data-field="${firstBad.key}"]`)?.focus();
      return;
    }
    sending.current = true;
    setStatus("sending");
    try {
      const hp = (formRef.current?.elements.namedItem(HP_FIELD) as HTMLInputElement | null)?.value ?? "";
      const res = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ values, source, [HP_FIELD]: hp }),
      });
      const data = (await res.json().catch(() => null)) as {
        ok?: boolean;
        errors?: Record<string, string>;
        message?: string;
      } | null;
      if (res.ok && data?.ok) {
        setStatus("done");
        return;
      }
      setStatus("idle");
      if (data?.errors) setErrors(data.errors);
      setFormError(data?.message || "Something went wrong, please try again.");
    } catch {
      setStatus("idle");
      setFormError("Something went wrong, please try again.");
    } finally {
      sending.current = false;
    }
  }

  if (status === "done") {
    return (
      <div
        ref={doneRef}
        tabIndex={-1}
        role="status"
        className="flex flex-col items-start gap-4 outline-none"
        data-testid="thank-you"
      >
        <CheckCircle2 size={32} strokeWidth={1.75} className="text-accent" aria-hidden="true" />
        <p className="font-heading text-2xl font-medium">{successMessage}</p>
      </div>
    );
  }

  return (
    <form ref={formRef} onSubmit={onSubmit} noValidate className="flex flex-col gap-6" data-testid="waitlist-form">
      {fields.map((f) => {
        const id = `wl-${f.key}`;
        const err = errors[f.key];
        const describedBy = err ? `${id}-error` : undefined;
        const label = (
          <Label htmlFor={id}>
            {f.label}
            {!f.required && f.type !== "email" && <span className="font-normal text-muted"> (optional)</span>}
          </Label>
        );
        return (
          <div key={f.key} className="flex flex-col gap-2">
            {f.type === "multiselect" ? (
              <fieldset className="flex flex-col gap-2" aria-describedby={describedBy}>
                <legend className="mb-2 text-sm font-medium">
                  {f.label}
                  {!f.required && <span className="font-normal text-muted"> (optional)</span>}
                </legend>
                {f.options.map((opt, i) => {
                  const current = Array.isArray(values[f.key]) ? (values[f.key] as string[]) : [];
                  return (
                    <label key={opt} className="flex min-h-11 items-center gap-3 text-base">
                      <input
                        type="checkbox"
                        className="size-5 accent-[var(--accent)]"
                        data-field={i === 0 ? f.key : undefined}
                        checked={current.includes(opt)}
                        onChange={(e) =>
                          setValue(f.key, e.target.checked ? [...current, opt] : current.filter((o) => o !== opt))
                        }
                      />
                      {opt}
                    </label>
                  );
                })}
              </fieldset>
            ) : f.type === "select" ? (
              <>
                {label}
                <Select
                  id={id}
                  name={f.key}
                  data-field={f.key}
                  value={typeof values[f.key] === "string" ? (values[f.key] as string) : ""}
                  onChange={(e) => setValue(f.key, e.target.value)}
                  aria-invalid={!!err}
                  aria-describedby={describedBy}
                >
                  <option value="">Choose one</option>
                  {f.options.map((opt) => (
                    <option key={opt} value={opt}>
                      {opt}
                    </option>
                  ))}
                </Select>
              </>
            ) : (
              <>
                {label}
                <Input
                  id={id}
                  name={f.key}
                  data-field={f.key}
                  type={f.type === "email" ? "email" : "text"}
                  inputMode={f.type === "email" ? "email" : undefined}
                  autoComplete={f.type === "email" ? "email" : f.key === "full_name" ? "name" : "off"}
                  maxLength={f.type === "email" ? 254 : 300}
                  value={typeof values[f.key] === "string" ? (values[f.key] as string) : ""}
                  onChange={(e) => setValue(f.key, e.target.value)}
                  aria-invalid={!!err}
                  aria-describedby={describedBy}
                />
              </>
            )}
            {err && (
              <p id={`${id}-error`} className="text-sm text-danger" role="alert">
                {err}
              </p>
            )}
          </div>
        );
      })}

      {/* Spam trap: invisible to people, never autofilled because of its random name. */}
      <div className="hp-field" aria-hidden="true">
        <input type="text" name={HP_FIELD} tabIndex={-1} autoComplete="off" defaultValue="" />
      </div>

      {formError && (
        <p role="alert" className="rounded-[var(--radius)] bg-danger-soft px-4 py-3 text-sm text-danger" data-testid="form-error">
          {formError}
        </p>
      )}

      <Button type="submit" disabled={status === "sending"} aria-busy={status === "sending"} className="w-full">
        {status === "sending" ? (
          <>
            <Loader2 size={20} strokeWidth={1.75} className="animate-spin motion-reduce:animate-none" aria-hidden="true" />
            Sending…
          </>
        ) : (
          submitLabel
        )}
      </Button>
      {privacyNote && <p className="text-sm text-muted">{privacyNote}</p>}
    </form>
  );
}

import type { FooterContent } from "@/lib/content";

export type FooterLink = { label: string; href: string };

export function SiteFooter({
  name,
  content,
  links,
}: {
  name: string;
  content: FooterContent;
  links: FooterLink[];
}) {
  return (
    <footer id="footer" className="border-t border-border bg-surface">
      <div className="container-page flex flex-col gap-8 py-10 md:flex-row md:items-start md:justify-between md:py-12">
        <div>
          <p className="font-heading text-xl font-semibold">{name}</p>
          {content.tagline && <p className="mt-1 text-muted">{content.tagline}</p>}
        </div>
        <div className="flex flex-col gap-4 md:items-end">
          {links.length > 0 && (
            <nav aria-label="Footer">
              <ul className="flex flex-wrap gap-x-6 gap-y-1">
                {links.map((l) => (
                  <li key={l.label + l.href}>
                    <a href={l.href} className="inline-flex min-h-11 items-center text-base underline-offset-4 hover:underline">
                      {l.label}
                    </a>
                  </li>
                ))}
              </ul>
            </nav>
          )}
          {content.legal && <p className="text-sm text-muted">{content.legal}</p>}
        </div>
      </div>
