}

export function DemoNotice() {
  return (
    <div
      role="note"
      data-testid="demo-notice"
      className="flex items-center justify-center overflow-hidden bg-foreground px-4 text-center text-sm text-background"
      style={{ height: "var(--notice-h)" }}
    >
      Demonstration site. Nothing here is final.
    </div>
