import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Theme } from "@/components/theme";
import { Benefits } from "@/components/site/benefits";
import { DemoNotice } from "@/components/site/demo-notice";
import { SiteFooter } from "@/components/site/footer";
import { SiteHeader, type HeaderLink } from "@/components/site/header";
import { Hero } from "@/components/site/hero";
import { Integrations } from "@/components/site/integrations";
import { Preview } from "@/components/site/preview";
import { Waitlist } from "@/components/site/waitlist";
import {
  type BenefitsContent,
  type FooterContent,
  type HeroContent,
  type IntegrationsContent,
  type PreviewContent,
  type WaitlistContent,
  BLOCK_IDS,
} from "@/lib/content";
import { getBlocks, getFields, getImage, getImagesByIds, getSite } from "@/lib/site-data";

export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const site = await getSite();
  if (!site) return {};
  const blocks = await getBlocks();
  const hero = blocks.find((b) => b.id === "hero");
  const heroImage = hero?.visible ? await getImage((hero.content as HeroContent).imageId) : null;
  const title = site.tagline ? `${site.name}: ${site.tagline}` : site.name;
  const description = site.description || undefined;
  return {
    title,
    description,
    openGraph: {
      title,
      description,
      type: "website",
      siteName: site.name,
      images:
        heroImage && heroImage.alt.trim()
          ? [{ url: heroImage.url, width: heroImage.width, height: heroImage.height, alt: heroImage.alt }]
          : undefined,
    },
    twitter: { card: heroImage ? "summary_large_image" : "summary", title, description },
  };
}

export default async function HomePage() {
  const site = await getSite();
  if (!site) notFound();
  const [blocks, fields] = await Promise.all([getBlocks(), getFields()]);
  const visible = blocks.filter((b) => b.visible);
  const visibleIds = new Set<string>(visible.map((b) => b.id));

  const byId = <T,>(id: string) => visible.find((b) => b.id === id)?.content as T | undefined;
  const hero = byId<HeroContent>("hero");
  const preview = byId<PreviewContent>("preview");
  const integrations = byId<IntegrationsContent>("integrations");
  const benefits = byId<BenefitsContent>("benefits");
  const waitlist = byId<WaitlistContent>("waitlist");
  const footer = byId<FooterContent>("footer");

  const images = await getImagesByIds([hero?.imageId, hero?.backgroundImageId, preview?.imageId]);

  // Navigation is derived from the visible blocks, and only has links that go somewhere real.
  const hasContact = site.contactEmail.trim() !== "";
  const links: HeaderLink[] = site.nav
    .filter((n) => (BLOCK_IDS as readonly string[]).includes(n.target) && visibleIds.has(n.target))
    .filter((n) => hasContact || !/contact/i.test(n.label))
    .map((n) => ({ label: n.label, href: `#${n.target}`, button: n.style === "button" }));

  const footerLinks = (footer?.links ?? []).filter((l) => {
    if (l.target.startsWith("#")) return visibleIds.has(l.target.slice(1));
    if (l.target.startsWith("mailto:")) return hasContact || true;
    return true;
  });

  const showNotice = site.demoNotice;

  return (
    <Theme accent={site.accent}>
      {showNotice && <DemoNotice />}
      <SiteHeader name={site.name} links={links} />
      <main>
        {visible
          .filter((b) => b.id !== "footer")
          .map((b) => {
            switch (b.id) {
              case "hero":
                return (
                  <Hero
                    key={b.id}
                    content={hero!}
                    image={hero!.imageId ? (images.get(hero!.imageId) ?? null) : null}
                    background={hero!.backgroundImageId ? (images.get(hero!.backgroundImageId) ?? null) : null}
                    demoNotice={showNotice}
                  />
                );
              case "integrations":
                return <Integrations key={b.id} content={integrations!} />;
              case "preview":
                return (
                  <Preview
                    key={b.id}
                    content={preview!}
                    image={preview!.imageId ? (images.get(preview!.imageId) ?? null) : null}
                  />
                );
              case "benefits":
                return <Benefits key={b.id} content={benefits!} />;
              case "waitlist":
                return <Waitlist key={b.id} content={waitlist!} fields={fields} />;
              default:
                return null;
            }
          })}
      </main>
      {footer && <SiteFooter name={site.name} content={footer} links={footerLinks} />}
    </Theme>
  );
}

