import Link from "next/link";
import { buttonVariants } from "@/components/ui/button";

export default function NotFound() {
  return (
    <main className="container-page flex min-h-screen flex-col items-start justify-center gap-6 py-16">
      <p className="text-sm text-muted">404</p>
      <h1 className="heading-section">This page does not exist.</h1>
      <p className="max-w-prose text-muted">The address may be mistyped, or the page may have moved.</p>
      <Link href="/" className={buttonVariants({ variant: "primary" })}>
        Back to the home page
      </Link>
