"use client";

import { Button } from "@/components/ui/button";

export default function ErrorPage({ reset }: { error: Error; reset: () => void }) {
  return (
    <main className="container-page flex min-h-screen flex-col items-start justify-center gap-6 py-16">
      <h1 className="heading-section">Something went wrong.</h1>
      <p className="max-w-prose text-muted">Please try again in a moment.</p>
      <Button onClick={reset}>Try again</Button>
    </main>
