}

import type { MetadataRoute } from "next";
import { siteUrl } from "@/lib/site-url";

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [{ userAgent: "*", allow: "/", disallow: ["/admin", "/api/"] }],
    sitemap: `${siteUrl()}/sitemap.xml`,
  };
}

import type { MetadataRoute } from "next";
import { siteUrl } from "@/lib/site-url";

export default function sitemap(): MetadataRoute.Sitemap {
  return [{ url: `${siteUrl()}/`, changeFrequency: "weekly", priority: 1 }];
}

/** Public address of the site, without a trailing slash. */
export function siteUrl(): string {
  const explicit = process.env.SITE_URL;
  if (explicit) return explicit.replace(/\/+$/, "");
  const vercel = process.env.VERCEL_PROJECT_PRODUCTION_URL;
  if (vercel) return `https://${vercel}`;
  return "http://localhost:3000";
}

/** Remove control characters other than tab, newline and carriage return (NUL breaks Postgres text). */
export function stripControl(value: string): string {
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "");
}

/** Trim, lower-case, keep letters, numbers, dash and underscore, cut at 60 characters; empty means "direct". */
export function cleanSource(raw: unknown): string {
  if (typeof raw !== "string") return "direct";
  const cleaned = raw
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_-]/g, "")
    .slice(0, 60);
  return cleaned === "" ? "direct" : cleaned;
}

/** The first forwarded address is the visitor's. */
export function clientKey(headers: Headers): string {
  const forwarded = headers.get("x-forwarded-for");
  const first = forwarded?.split(",")[0]?.trim();
  if (first) return first.slice(0, 64);
  return (headers.get("x-real-ip") ?? "unknown").slice(0, 64);
}

import "server-only";
import { and, count, desc, eq, gt, lt } from "drizzle-orm";
import { db } from "@/db";
import { rateEvents } from "@/db/schema";

export const TEN_MINUTES = 10 * 60 * 1000;

/**
 * Counts one event for (scope, key) and says whether it is within `max` events per window.
 * The event is recorded first and removed again when refused, so parallel requests cannot slip past.
 */
export async function allowEvent(scope: string, key: string, max: number, windowMs = TEN_MINUTES): Promise<boolean> {
  const [row] = await db.insert(rateEvents).values({ scope, key }).returning({ id: rateEvents.id });
  const since = new Date(Date.now() - windowMs);
  const [{ n }] = await db
    .select({ n: count() })
    .from(rateEvents)
    .where(and(eq(rateEvents.scope, scope), eq(rateEvents.key, key), gt(rateEvents.createdAt, since)));
  if (n > max) {
    await db.delete(rateEvents).where(eq(rateEvents.id, row.id));
    return false;
  }
  if (Math.random() < 0.02) {
    await db.delete(rateEvents).where(lt(rateEvents.createdAt, new Date(Date.now() - 24 * 3_600_000)));
  }
  return true;
}

const SIGN_IN_SCOPE = "signin-failed";

/** Locked when the last five failures happened within ten minutes of each other and the latest is under ten minutes old. */
export async function isSignInLocked(key: string): Promise<boolean> {
  const rows = await db
    .select({ at: rateEvents.createdAt })
    .from(rateEvents)
    .where(and(eq(rateEvents.scope, SIGN_IN_SCOPE), eq(rateEvents.key, key)))
    .orderBy(desc(rateEvents.createdAt))
    .limit(5);
  if (rows.length < 5) return false;
  const newest = rows[0].at.getTime();
  const oldest = rows[4].at.getTime();
  return newest - oldest <= TEN_MINUTES && Date.now() - newest < TEN_MINUTES;
}

export async function recordSignInFailure(key: string): Promise<void> {
  await db.insert(rateEvents).values({ scope: SIGN_IN_SCOPE, key });
}

export async function clearSignInFailures(key: string): Promise<void> {
  await db.delete(rateEvents).where(and(eq(rateEvents.scope, SIGN_IN_SCOPE), eq(rateEvents.key, key)));
}

import "server-only";
import { desc } from "drizzle-orm";
import { db } from "@/db";
import { problems } from "@/db/schema";

export type Problem = { kind: string; message: string; at: Date };

// If the database itself is down the problem cannot be saved there, so it is also kept in memory.
const memory: Problem[] = [];

export async function recordProblem(kind: string, error: unknown): Promise<void> {
  const message = (error instanceof Error ? error.message : String(error)).slice(0, 300);
  console.error(`[problem:${kind}]`, message);
  memory.unshift({ kind, message, at: new Date() });
  memory.length = Math.min(memory.length, 20);
  try {
    await db.insert(problems).values({ kind, message });
  } catch {
    // already kept in memory and in the server log
  }
}

export async function recentProblems(limit = 10): Promise<Problem[]> {
  let stored: Problem[] = [];
  try {
    const rows = await db.select().from(problems).orderBy(desc(problems.createdAt)).limit(limit);
    stored = rows.map((r) => ({ kind: r.kind, message: r.message, at: r.createdAt }));
  } catch {
    // database unreachable: show what memory has
  }
  const seen = new Set(stored.map((p) => `${p.kind}|${p.message}|${Math.floor(p.at.getTime() / 1000)}`));
  const extra = memory.filter((p) => !seen.has(`${p.kind}|${p.message}|${Math.floor(p.at.getTime() / 1000)}`));
  return [...stored, ...extra].sort((a, b) => b.at.getTime() - a.at.getTime()).slice(0, limit);
}

