import "server-only";
import { z } from "zod";
import { db } from "@/db";
import { signups } from "@/db/schema";
import { MAX_EMAIL, MAX_TEXT_ANSWER, type FieldRow } from "@/lib/content";
import { HP_FIELD } from "@/lib/honeypot";
import { recordProblem } from "@/lib/problems";
import { allowEvent } from "@/lib/rate-limit";
import { cleanSource, stripControl } from "@/lib/sanitize";
import { getFields } from "@/lib/site-data";

export type SignupResponse = {
  status: number;
  body: { ok: boolean; errors?: Record<string, string>; message?: string };
};

const bodySchema = z.object({
  values: z.record(z.string(), z.unknown()).default({}),
  source: z.unknown().optional(),
});

const EMAIL_MESSAGE = "Please enter a valid email address";
const emailSchema = z.string().max(MAX_EMAIL).pipe(z.email());

export type Validated =
  | { ok: true; email: string; answers: Record<string, string | string[]> }
  | { ok: false; errors: Record<string, string>; tampered: boolean };

/** Check every answer against the form's current fields and options. */
export function validateAnswers(fields: FieldRow[], values: Record<string, unknown>): Validated {
  const errors: Record<string, string> = {};
  const answers: Record<string, string | string[]> = {};
  let email = "";
  let tampered = false;
  let emailSeen = false;

  for (const f of fields) {
    const raw = values[f.key];
    if (f.type === "email") {
      if (emailSeen) continue; // only the first email question is the signup's address
      emailSeen = true;
      const text = typeof raw === "string" ? raw.trim().toLowerCase() : "";
      const parsed = emailSchema.safeParse(text);
      if (!parsed.success) errors[f.key] = EMAIL_MESSAGE;
      else email = parsed.data;
      continue;
    }
    if (f.type === "text") {
      if (raw !== undefined && typeof raw !== "string") {
        tampered = true;
        continue;
      }
      const text = stripControl(typeof raw === "string" ? raw : "").trim();
      if (text === "") {
        if (f.required) errors[f.key] = `Please answer “${f.label}”`;
        continue;
      }
      if (text.length > MAX_TEXT_ANSWER) {
        errors[f.key] = `“${f.label}” is too long (${MAX_TEXT_ANSWER} characters at most)`;
        continue;
      }
      answers[f.key] = text;
      continue;
    }
    if (f.type === "select") {
      if (raw !== undefined && typeof raw !== "string") {
        tampered = true;
        continue;
      }
      const text = typeof raw === "string" ? raw : "";
      if (text === "") {
        if (f.required) errors[f.key] = `Please answer “${f.label}”`;
        continue;
      }
      if (!f.options.includes(text)) {
        tampered = true;
        continue;
      }
      answers[f.key] = text;
      continue;
    }
    if (f.type === "multiselect") {
      if (raw !== undefined && !Array.isArray(raw)) {
        tampered = true;
        continue;
      }
      const list = Array.isArray(raw) ? raw : [];
      if (list.some((v) => typeof v !== "string" || !f.options.includes(v))) {
        tampered = true;
        continue;
      }
      const unique = [...new Set(list as string[])];
      if (unique.length === 0) {
        if (f.required) errors[f.key] = `Please answer “${f.label}”`;
        continue;
      }
      answers[f.key] = unique;
    }
  }

  if (tampered || Object.keys(errors).length > 0 || !email) {
    if (!email && !errors && !tampered) errors.email = EMAIL_MESSAGE;
    return { ok: false, errors, tampered };
  }
  return { ok: true, email, answers };
}

export async function handleSignup(
  rawBody: unknown,
  ip: string,
  options: { forceFailure?: boolean } = {},
): Promise<SignupResponse> {
  const record = (rawBody ?? {}) as Record<string, unknown>;

  // Honeypot: accepted silently, nothing stored.
  const trap = record[HP_FIELD];
  if (typeof trap === "string" && trap.trim() !== "") return { status: 200, body: { ok: true } };

  const parsedBody = bodySchema.safeParse(rawBody);
  if (!parsedBody.success) {
    return { status: 400, body: { ok: false, message: "Please check your answers." } };
  }

  try {
    if (options.forceFailure) throw new Error("Simulated database failure (test hook)");
    const fields = await getFields();
    const result = validateAnswers(fields, parsedBody.data.values);
    if (!result.ok) {
      if (result.tampered) {
        return { status: 400, body: { ok: false, message: "Please check your answers." } };
      }
      return { status: 400, body: { ok: false, errors: result.errors } };
    }

    const allowed = await allowEvent("signup", ip, 5);
    if (!allowed) {
      return {
        status: 429,
        body: { ok: false, message: "Too many sign-ups from this connection. Please try again in a few minutes." },
      };
    }

    // A repeat email changes nothing and reveals nothing.
    await db
      .insert(signups)
      .values({
        email: result.email,
        answers: result.answers,
        source: cleanSource(parsedBody.data.source),
      })
      .onConflictDoNothing({ target: signups.email });
    return { status: 200, body: { ok: true } };
  } catch (error) {
    await recordProblem("signup", error);
    return { status: 500, body: { ok: false, message: "Something went wrong, please try again." } };
  }
}

import { NextResponse } from "next/server";
import { clientKey } from "@/lib/sanitize";
import { handleSignup } from "@/lib/signup";

export const dynamic = "force-dynamic";

export async function POST(request: Request) {
  let body: unknown = null;
  try {
    const text = await request.text();
    if (text.length > 50_000) {
      return NextResponse.json({ ok: false, message: "Please check your answers." }, { status: 413 });
    }
    body = JSON.parse(text);
  } catch {
    return NextResponse.json({ ok: false, message: "Please check your answers." }, { status: 400 });
  }
  const forceFailure =
    process.env.ENABLE_TEST_HOOKS === "1" && request.headers.get("x-test-fail") === "db";
  const result = await handleSignup(body, clientKey(request.headers), { forceFailure });
  return NextResponse.json(result.body, { status: result.status });
}

import "server-only";
import { randomUUID } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

export const UPLOAD_DIR = path.join(process.cwd(), ".uploads");
export const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
export const ALLOWED_TYPES = { jpg: "image/jpeg", png: "image/png", webp: "image/webp" } as const;
export type ImageExt = keyof typeof ALLOWED_TYPES;

/** Local disk in development; Vercel Blob when deployed (needs BLOB_READ_WRITE_TOKEN). */
export function storageStatus(): { ok: true } | { ok: false; reason: string } {
  if (process.env.VERCEL && !process.env.BLOB_READ_WRITE_TOKEN) {
    return {
      ok: false,
      reason:
        "Images cannot be uploaded yet: image storage is not set up for this deployed site (the BLOB_READ_WRITE_TOKEN setting is missing).",
    };
  }
  return { ok: true };
}

export async function storeImage(buffer: Buffer, ext: ImageExt): Promise<string> {
  const name = `${randomUUID()}.${ext}`;
  if (process.env.VERCEL) {
    const { put } = await import("@vercel/blob");
    const blob = await put(`uploads/${name}`, buffer, {
      access: "public",
      contentType: ALLOWED_TYPES[ext],
      token: process.env.BLOB_READ_WRITE_TOKEN,
    });
    return blob.url;
  }
  await mkdir(UPLOAD_DIR, { recursive: true });
  await writeFile(path.join(UPLOAD_DIR, name), buffer);
  return `/uploads/${name}`;
}

export async function readLocalImage(name: string): Promise<{ data: Buffer; contentType: string } | null> {
  const match = /^[0-9a-f-]{36}\.(jpg|png|webp)$/.exec(name);
  if (!match) return null;
  try {
    const data = await readFile(path.join(UPLOAD_DIR, name));
    return { data, contentType: ALLOWED_TYPES[match[1] as ImageExt] };
  } catch {
    return null;
  }
}

import { readLocalImage } from "@/lib/storage";

export const dynamic = "force-dynamic";

export async function GET(_req: Request, { params }: { params: Promise<{ name: string }> }) {
