      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

import { imageSize } from "image-size";
import { NextResponse } from "next/server";
import { z } from "zod";
import { db } from "@/db";
import { images } from "@/db/schema";
import { isOwner } from "@/lib/auth";
import { recordProblem } from "@/lib/problems";
import { ALLOWED_TYPES, MAX_IMAGE_BYTES, storageStatus, storeImage, type ImageExt } from "@/lib/storage";

export const dynamic = "force-dynamic";

const altSchema = z
  .string()
  .trim()
  .min(1, "Please describe the image in a few words (this is read aloud to people who cannot see it).")
  .max(200, "Please use at most 200 characters.");

export async function POST(request: Request) {
  if (!(await isOwner())) return NextResponse.json({ error: "Not signed in" }, { status: 401 });

  const status = storageStatus();
  if (!status.ok) return NextResponse.json({ errors: { file: status.reason } }, { status: 503 });

  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return NextResponse.json({ errors: { file: "The upload could not be read." } }, { status: 400 });
  }

  const errors: Record<string, string> = {};
  const alt = altSchema.safeParse(form.get("alt") ?? "");
  if (!alt.success) errors.alt = alt.error.issues[0].message;

  const file = form.get("file");
  let buffer: Buffer | null = null;
  let ext: ImageExt | null = null;
  let width = 0;
  let height = 0;
  if (!(file instanceof File) || file.size === 0) {
    errors.file = "Please choose an image file.";
  } else if (file.size > MAX_IMAGE_BYTES) {
    errors.file = "That file is too large. Please use an image of 8 MB or less.";
  } else {
    buffer = Buffer.from(await file.arrayBuffer());
    try {
      const info = imageSize(buffer);
      const type = info.type === "jpeg" ? "jpg" : info.type;
      if (type && type in ALLOWED_TYPES && info.width && info.height) {
        ext = type as ImageExt;
        width = info.width;
        height = info.height;
      }
    } catch {
      // handled below
    }
    if (!ext) errors.file = "That file type is not supported. Please use a JPEG, PNG or WebP image.";
  }

  if (Object.keys(errors).length > 0 || !buffer || !ext || !alt.success) {
    return NextResponse.json({ errors }, { status: 400 });
  }

  try {
    const url = await storeImage(buffer, ext);
    const [row] = await db
      .insert(images)
      .values({ url, alt: alt.data, width, height })
      .returning();
    return NextResponse.json({ id: row.id, url: row.url, alt: row.alt, width: row.width, height: row.height });
  } catch (error) {
    await recordProblem("upload", error);
    return NextResponse.json({ errors: { file: "The image could not be saved. Please try again." } }, { status: 500 });
  }
}

const DAY = 86_400_000;

export type GoalStatus = {
  text: string;
  percent: number;
  state: "running" | "reached" | "ended";
  daysLeft: number;
};

/** Words for the goal progress. The days left never go below zero. */
export function goalStatus(opts: {
  total: number;
  target: number;
  days: number | null;
  launchedAt: Date;
  now?: Date;
}): GoalStatus {
  const { total, target, days, launchedAt } = opts;
  const now = (opts.now ?? new Date()).getTime();
  const percent = target > 0 ? Math.min(100, Math.round((total / target) * 100)) : 0;
  const end = days ? launchedAt.getTime() + days * DAY : null;
  const daysLeft = end === null ? 0 : Math.max(0, Math.ceil((end - now) / DAY));
  if (total >= target) {
    return { text: `Goal reached: ${total} of ${target}`, percent, state: "reached", daysLeft };
  }
  if (end !== null && now >= end) {
    return { text: `Goal period ended: ${total} of ${target}`, percent, state: "ended", daysLeft: 0 };
  }
  if (end === null) {
    return { text: `${total} of ${target}`, percent, state: "running", daysLeft: 0 };
  }
  return {
    text: `${total} of ${target} in ${days} days, ${daysLeft} ${daysLeft === 1 ? "day" : "days"} left`,
    percent,
    state: "running",
    daysLeft,
  };
}

/** One CSV cell. Cells a spreadsheet would run as a formula get a leading apostrophe. */
export function csvCell(value: unknown): string {
  let text = value === null || value === undefined ? "" : String(value);
  if (/^[=+\-@\t\r]/.test(text)) text = `'${text}`;
  if (/[",\n\r]/.test(text)) text = `"${text.replace(/"/g, '""')}"`;
  return text;
}

export function csvRow(cells: unknown[]): string {
  return cells.map(csvCell).join(",") + "\r\n";
}

export const CSV_BOM = "\uFEFF";

import { desc, sql } from "drizzle-orm";
import { db } from "@/db";
import { signups } from "@/db/schema";
import { isOwner } from "@/lib/auth";
import { CSV_BOM, csvRow } from "@/lib/csv";
import { getFields } from "@/lib/site-data";

export const dynamic = "force-dynamic";

const BATCH = 500;

export async function GET() {
  if (!(await isOwner())) return new Response("Not signed in", { status: 401 });

  const fields = await getFields();
  const labelByKey = new Map(fields.filter((f) => f.type !== "email").map((f) => [f.key, f.label]));
  // Answers to questions that were removed later keep their own column, named by the old key.
  const keyRows = await db.execute<{ k: string }>(
    sql`select distinct jsonb_object_keys(${signups.answers}) as k from ${signups}`,
  );
  const extraKeys = keyRows.rows.map((r) => r.k).filter((k) => !labelByKey.has(k)).sort();
  const columns = [...labelByKey.keys(), ...extraKeys];
  const header = ["Email", ...columns.map((k) => labelByKey.get(k) ?? `${k} (removed question)`), "Source", "Signed up at", "Sample"];

  let offset = 0;
  let sentHeader = false;
  const encoder = new TextEncoder();

  const stream = new ReadableStream<Uint8Array>({
    async pull(controller) {
      try {
        if (!sentHeader) {
          sentHeader = true;
          controller.enqueue(encoder.encode(CSV_BOM + csvRow(header)));
          return;
        }
        const rows = await db
          .select()
          .from(signups)
          .orderBy(desc(signups.createdAt), desc(signups.id))
          .limit(BATCH)
          .offset(offset);
        if (rows.length === 0) {
          controller.close();
          return;
        }
        offset += rows.length;
        let chunk = "";
        for (const r of rows) {
          const cells = columns.map((k) => {
            const v = r.answers?.[k];
            return Array.isArray(v) ? v.join("; ") : (v ?? "");
          });
          chunk += csvRow([r.email, ...cells, r.source, r.createdAt.toISOString(), r.isSample ? "yes" : "no"]);
        }
        controller.enqueue(encoder.encode(chunk));
        if (rows.length < BATCH) controller.close();
      } catch (error) {
        controller.error(error);
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": 'attachment; filename="signups.csv"',
      "Cache-Control": "no-store",
    },
  });
}

