"use server";

import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { startSession } from "@/lib/auth";
import { verifyPassword } from "@/lib/password";
import { isSignInLocked, recordSignInFailure } from "@/lib/rate-limit";
import { clientKey } from "@/lib/sanitize";

export type SignInState = { error?: string; email?: string };

const LOCKED = "Too many attempts. Sign-in is locked for ten minutes. Please try again later.";

export async function signInAction(_prev: SignInState, formData: FormData): Promise<SignInState> {
  const email = String(formData.get("email") ?? "").trim().slice(0, 254);
  const password = String(formData.get("password") ?? "").slice(0, 200);
  const key = clientKey(await headers());

  try {
    if (await isSignInLocked(key)) return { error: LOCKED, email };

    const adminEmail = (process.env.ADMIN_EMAIL ?? "").trim().toLowerCase();
    // Always check the password so a wrong email and a wrong password take the same time.
    const passwordOk = verifyPassword(password, process.env.ADMIN_PASSWORD_HASH ?? "");
    if (adminEmail !== "" && email.toLowerCase() === adminEmail && passwordOk) {
      await startSession(adminEmail);
    } else {
      await recordSignInFailure(key);
      return { error: (await isSignInLocked(key)) ? LOCKED : "The email or password is not right.", email };
    }
  } catch (error) {
    // redirect() below must not be caught, so only the checks above are inside the try.
    console.error("Sign-in failed:", error instanceof Error ? error.message : error);
    return { error: "Something went wrong. Please try again.", email };
  }
  redirect("/admin");
}

