      <header className="border-b border-border bg-surface">
        <div className="container-page flex flex-wrap items-center justify-between gap-4 py-3">
          <div className="flex flex-wrap items-center gap-4">
            <p className="font-heading text-lg font-semibold">{site?.name ?? "Owner area"}</p>
            <AdminNav />
          </div>
          <div className="flex items-center gap-2">
            <Link href="/" className="inline-flex min-h-11 items-center px-3 text-base text-muted hover:text-foreground">
              View site
            </Link>
            <form action={signOutAction}>
              <Button type="submit" variant="secondary" size="sm">
                <LogOut size={16} strokeWidth={1.75} aria-hidden="true" />
                Sign out
              </Button>
            </form>
          </div>
        </div>
      </header>
      <main className="container-page py-10">{children}</main>
    </Theme>
  );
}

function channel(c: number): number {
  const s = c / 255;
  return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
}

export function luminance(r: number, g: number, b: number): number {
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
}

export function contrastRatio(a: [number, number, number], b: [number, number, number]): number {
  const la = luminance(...a);
  const lb = luminance(...b);
  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

export function hexToRgb(hex: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

