async function waitlistWarning(): Promise<string | undefined> {
  const rows = await db.select({ id: blocks.id, visible: blocks.visible }).from(blocks);
  const waitlist = rows.find((r) => r.id === "waitlist");
  if (!waitlist || !waitlist.visible) {
    return "The Waitlist block is hidden, so nobody can join. Show it again to collect sign-ups.";
  }
  return undefined;
}

export async function saveBlockAction(
  id: string,
  visible: boolean,
  input: Record<string, unknown>,
  alts: Record<string, string>,
): Promise<SaveResult> {
  await requireOwner();
  if (!(BLOCK_IDS as readonly string[]).includes(id)) return GENERIC_FAILURE;
  const blockId = id as BlockId;
  try {
    const [existing] = await db.select().from(blocks).where(eq(blocks.id, blockId)).limit(1);
    if (!existing) return GENERIC_FAILURE;

    // Clean list inputs first, remembering the original row numbers for error messages.
    const errors: Record<string, string> = {};
    const draft: Record<string, unknown> = { ...input };
    if (blockId === "benefits" && Array.isArray(draft.items)) {
      const items = draft.items as { title?: string; text?: string; hidden?: boolean }[];
      items.forEach((it, i) => {
        if (!(it.title ?? "").trim() && (it.text ?? "").trim()) errors[`items.${i}.title`] = "Please enter a title.";
      });
      draft.items = items.filter((it) => (it.title ?? "").trim() || (it.text ?? "").trim());
    }
    if (blockId === "integrations" && Array.isArray(draft.items)) {
      draft.items = (draft.items as string[]).map((s) => String(s).trim()).filter(Boolean);
    }
    if (blockId === "waitlist" && Array.isArray(draft.perks)) {
      draft.perks = (draft.perks as string[]).map((s) => String(s).trim()).filter(Boolean);
    }
    if (blockId === "footer" && Array.isArray(draft.links)) {
      draft.links = (draft.links as { label?: string; target?: string }[]).filter(
        (l) => (l.label ?? "").trim() || (l.target ?? "").trim(),
      );
    }

    const merged = { ...(existing.content as Record<string, unknown>), ...draft };
    const parsed = BLOCK_SCHEMAS[blockId].safeParse(merged);
    if (!parsed.success) Object.assign(errors, issuesToErrors(parsed.error));
    if (Object.keys(errors).length > 0 || !parsed.success) {
      return { ok: false, errors, message: "Some values need attention. Nothing was saved." };
    }

    // Every image that is shown needs a description.
    const data = parsed.data as Record<string, unknown>;
    const imageFields = ["imageId", "backgroundImageId"].filter((f) => typeof data[f] === "string");
    const altUpdates: { id: string; alt: string; field: string }[] = [];
    for (const field of imageFields) {
      const imageId = data[field] as string;
      const alt = (alts[imageId] ?? "").trim();
      if (alt === "") {
        const [row] = await db.select({ alt: images.alt }).from(images).where(eq(images.id, imageId)).limit(1);
        if (!row || row.alt.trim() === "") {
          errors[field] = "Please describe the image in a few words.";
          continue;
        }
      } else if (alt.length > 200) {
        errors[field] = "Please use at most 200 characters for the description.";
        continue;
      } else {
        altUpdates.push({ id: imageId, alt, field });
      }
    }
    if (Object.keys(errors).length > 0) {
      return { ok: false, errors, message: "Some values need attention. Nothing was saved." };
    }

    await db.transaction(async (tx) => {
      for (const u of altUpdates) await tx.update(images).set({ alt: u.alt }).where(eq(images.id, u.id));
      await tx.update(blocks).set({ content: data, visible }).where(eq(blocks.id, blockId));
    });
    revalidatePath("/");
    revalidatePath("/admin/page");
    const warning = await waitlistWarning();
    return { ok: true, errors: {}, message: `${BLOCK_NAMES[blockId]} saved.`, warning };
  } catch (error) {
    await recordProblem("save-block", error);
    return GENERIC_FAILURE;
  }
}

// ---------- form questions ----------

const fieldInput = z.object({
  key: z.string().max(60).default(""),
  label: z.string().trim().min(1, "Please enter the question.").max(80, "Please use at most 80 characters."),
  type: z.enum(FIELD_TYPES),
  required: z.boolean().default(false),
  options: z.array(z.string()).default([]),
});

const formInput = z.object({
  fields: z.array(fieldInput).min(1, "The form needs at least an email question.").max(12, "Please keep at most 12 questions."),
  form: waitlistFormSchema,
});
export type FormInput = z.input<typeof formInput>;

function slug(label: string): string {
  const base = label
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .slice(0, 30);
  return base || "question";
}

export async function saveFormAction(input: unknown): Promise<SaveResult> {
  await requireOwner();
  const parsed = formInput.safeParse(input);
  if (!parsed.success) {
    return { ok: false, errors: issuesToErrors(parsed.error), message: "Some values need attention. Nothing was saved." };
  }
  const { fields, form } = parsed.data;
  const errors: Record<string, string> = {};

  const emailIdx = fields.map((f, i) => (f.type === "email" ? i : -1)).filter((i) => i >= 0);
  if (emailIdx.length === 0) errors.fields = "The form needs an email question.";
  if (emailIdx.length > 1) errors.fields = "The form can have only one email question.";

  const cleaned = fields.map((f, i) => {
    const options = [...new Set(f.options.map((o) => o.trim()).filter(Boolean))];
    if ((f.type === "select" || f.type === "multiselect")) {
      if (options.length < 2) errors[`fields.${i}.options`] = "Please give at least two options, one per line.";
      if (options.some((o) => o.length > 80)) errors[`fields.${i}.options`] = "Each option can have at most 80 characters.";
      if (options.length > 20) errors[`fields.${i}.options`] = "Please keep at most 20 options.";
    }
    return {
      ...f,
      required: f.type === "email" ? true : f.required,
      options: f.type === "select" || f.type === "multiselect" ? options : [],
    };
  });
  if (Object.keys(errors).length > 0) {
    return { ok: false, errors, message: "Some values need attention. Nothing was saved." };
  }

  try {
    const existing = await db.select({ key: formFields.key, type: formFields.type }).from(formFields);
    const existingKeys = new Set(existing.map((e) => e.key));
    const used = new Set<string>();
    const rows = cleaned.map((f, position) => {
      let key = f.key;
      if (!key || !existingKeys.has(key)) {
        const base = slug(f.label);
        key = base;
        let n = 2;
        while (existingKeys.has(key) || used.has(key)) key = `${base}_${n++}`;
      }
      used.add(key);
      return { key, label: f.label, type: f.type, required: f.required, options: f.options, position };
    });
    if (new Set(rows.map((r) => r.key)).size !== rows.length) {
      return { ok: false, errors: { fields: "Two questions share the same key." }, message: "Nothing was saved." };
    }
    await db.transaction(async (tx) => {
      await tx.delete(formFields).where(notInArray(formFields.key, rows.map((r) => r.key)));
      for (const r of rows) {
        await tx
          .insert(formFields)
          .values(r)
          .onConflictDoUpdate({
            target: formFields.key,
            set: { label: r.label, type: r.type, required: r.required, options: r.options, position: r.position },
          });
      }
      const [wl] = await tx.select().from(blocks).where(eq(blocks.id, "waitlist")).limit(1);
      if (wl) {
        await tx
          .update(blocks)
          .set({ content: { ...(wl.content as Record<string, unknown>), form } })
          .where(eq(blocks.id, "waitlist"));
      }
    });
    revalidatePath("/");
    revalidatePath("/admin/form");
    revalidatePath("/admin");
    return { ok: true, errors: {}, message: "Form saved.", warning: await waitlistWarning() };
  } catch (error) {
    await recordProblem("save-form", error);
    return GENERIC_FAILURE;
  }
}

// ---------- settings ----------

const optionalInt = (min: number, max: number, what: string) =>
  z
    .union([z.number(), z.string(), z.null()])
    .transform((v, ctx) => {
      if (v === null || (typeof v === "string" && v.trim() === "")) return null;
      const n = typeof v === "number" ? v : Number(v);
      if (!Number.isInteger(n) || n < min || n > max) {
        ctx.addIssue({ code: "custom", message: `Please enter a whole number from ${min} to ${max} for ${what}, or leave it empty.` });
        return z.NEVER;
      }
      return n;
    });

const settingsInput = z.object({
  name: z.string().trim().min(1, "Please enter the site name.").max(60, "Please use at most 60 characters."),
  tagline: z.string().trim().max(160, "Please use at most 160 characters.").default(""),
  description: z.string().trim().max(300, "Please use at most 300 characters.").default(""),
  contactEmail: z
    .string()
    .trim()
    .max(254)
    .refine((v) => v === "" || z.email().safeParse(v).success, "Please enter a valid email address, or leave it empty."),
  accent: z.string().trim().regex(/^#[0-9a-fA-F]{6}$/, "Please enter a colour like #3f6f73."),
  demoNotice: z.boolean().default(false),
  successTargetSignups: optionalInt(1, 1_000_000, "the goal"),
  successTargetDays: optionalInt(1, 365, "the goal period"),
  launchedAt: z.string().trim().regex(/^\d{4}-\d{2}-\d{2}$/, "Please choose a start date."),
});

export async function saveSettingsAction(input: unknown): Promise<SaveResult> {
  await requireOwner();
  const parsed = settingsInput.safeParse(input);
  if (!parsed.success) {
    return { ok: false, errors: issuesToErrors(parsed.error), message: "Some values need attention. Nothing was saved." };
  }
  const v = parsed.data;
  const rgb = hexToRgb(v.accent)!;
  if (contrastRatio(rgb, [255, 255, 255]) < 4.5) {
    return {
      ok: false,
      errors: { accent: "That colour is too light: white text on it would be hard to read. Please choose a darker one." },
      message: "Some values need attention. Nothing was saved.",
    };
  }
  const launched = new Date(`${v.launchedAt}T00:00:00.000Z`);
  if (Number.isNaN(launched.getTime())) {
    return { ok: false, errors: { launchedAt: "Please choose a valid date." }, message: "Nothing was saved." };
  }
  try {
    await db
      .update(site)
      .set({
        name: v.name,
        tagline: v.tagline,
        description: v.description,
        contactEmail: v.contactEmail,
        accent: v.accent.toLowerCase(),
        demoNotice: v.demoNotice,
        successTargetSignups: v.successTargetSignups,
        successTargetDays: v.successTargetDays,
        launchedAt: launched,
      })
      .where(eq(site.id, 1));
    revalidatePath("/", "layout");
    return { ok: true, errors: {}, message: "Settings saved." };
  } catch (error) {
    await recordProblem("save-settings", error);
    return GENERIC_FAILURE;
  }
}

