                  {r.label}
                  {r.removed && <span className="ml-2 rounded-full bg-accent-soft px-2 py-0.5 text-xs">removed</span>}
                </span>
                <span className="font-medium tabular-nums">{r.n}</span>
              </div>
              <div className="mt-1 h-2 rounded-full bg-accent-soft" aria-hidden="true">
                <div className="h-2 rounded-full bg-accent" style={{ width: `${(r.n / max) * 100}%` }} />
              </div>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export default async function SignupsPage({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; page?: string }>;
}) {
  const sp = await searchParams;
  const q = (sp.q ?? "").trim().slice(0, 100);
  const page = Math.max(1, Math.min(100000, parseInt(sp.page ?? "1", 10) || 1));

  const [site, fields] = await Promise.all([getSite(), getFields()]);
  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);

  const real = eq(signups.isSample, false);
  const [[{ total }], [{ today }], [{ samples }], sourceRows, answerRows, blockRows, problems] = await Promise.all([
    db.select({ total: count() }).from(signups).where(real),
    db.select({ today: count() }).from(signups).where(and(real, gte(signups.createdAt, startOfToday))),
    db.select({ samples: count() }).from(signups).where(eq(signups.isSample, true)),
    db
      .select({ source: signups.source, n: count() })
      .from(signups)
      .where(real)
      .groupBy(signups.source)
      .orderBy(desc(count())),
    db.select({ answers: signups.answers }).from(signups).where(real),
    db.select({ id: blocks.id, visible: blocks.visible }).from(blocks),
    recentProblems(10),
  ]);

  const escapedQ = q.replace(/[\\%_]/g, (c) => `\\${c}`);
  const filter = q ? ilike(signups.email, `%${escapedQ}%`) : undefined;
  const [{ matching }] = await db.select({ matching: count() }).from(signups).where(filter);
  const pageCount = Math.max(1, Math.ceil(matching / PAGE_SIZE));
  const current = Math.min(page, pageCount);
  const list = await db
    .select()
    .from(signups)
    .where(filter)
    .orderBy(desc(signups.createdAt), desc(signups.id))
    .limit(PAGE_SIZE)
    .offset((current - 1) * PAGE_SIZE);

  const goal =
    site?.successTargetSignups
      ? goalStatus({
          total,
          target: site.successTargetSignups,
          days: site.successTargetDays,
          launchedAt: site.launchedAt,
        })
      : null;

  // Counts per option for select questions. Options removed later are still counted, marked "removed".
  const choiceFields = fields.filter((f) => f.type === "select" || f.type === "multiselect");
  const breakdowns = choiceFields.map((f) => {
    const counts = new Map<string, number>(f.options.map((o) => [o, 0]));
    const removed = new Set<string>();
    for (const row of answerRows) {
      const v = row.answers?.[f.key];
      const values = Array.isArray(v) ? v : typeof v === "string" && v !== "" ? [v] : [];
      for (const value of values) {
        if (!counts.has(value)) {
          counts.set(value, 0);
          removed.add(value);
        }
        counts.set(value, (counts.get(value) ?? 0) + 1);
      }
    }
    return {
      field: f,
      rows: [...counts.entries()].map(([label, n]) => ({ label, n, removed: removed.has(label) })),
    };
  });

  const labelFor = new Map(fields.map((f) => [f.key, f.label]));
  const waitlistHidden = blockRows.some((b) => b.id === "waitlist" && !b.visible);

  const h = await headers();
  const host = h.get("x-forwarded-host") ?? h.get("host");
  const address = host ? `${h.get("x-forwarded-proto") ?? "http"}://${host}` : siteUrl();

  const qs = (p: number) => {
    const params = new URLSearchParams();
    if (q) params.set("q", q);
    if (p > 1) params.set("page", String(p));
    const s = params.toString();
    return s ? `/admin?${s}` : "/admin";
  };

  return (
    <div className="flex flex-col gap-10">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <h1 className="heading-section">Signups</h1>
        <a href="/api/admin/signups.csv" download className={buttonVariants({ variant: "secondary" })}>
          <Download size={20} strokeWidth={1.75} aria-hidden="true" />
          Download CSV
        </a>
      </div>

      {waitlistHidden && (
        <p role="alert" className="flex items-start gap-3 rounded-[var(--radius)] bg-danger-soft px-4 py-3 text-danger">
          <AlertTriangle size={20} strokeWidth={1.75} className="mt-0.5 shrink-0" aria-hidden="true" />
          The Waitlist block is hidden, so nobody can join. Show it again on the Page screen.
        </p>
      )}

      <section aria-label="Summary" className="grid gap-4 md:grid-cols-3">
        <div className="rounded-[var(--radius)] border border-border bg-surface p-5">
          <p className="text-sm text-muted">Total signups</p>
          <p className="mt-1 font-heading text-4xl font-medium" data-testid="total">{total}</p>
        </div>
        <div className="rounded-[var(--radius)] border border-border bg-surface p-5">
          <p className="text-sm text-muted">Signups today</p>
