"use client";

import { useRef, useState } from "react";
import { ImageIcon, Loader2, Trash2, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export type ImageValue = { id: string; url: string; alt: string; width: number; height: number };

/** Upload, describe and remove one image. The description (alt text) is required. */
export function ImageField({
  name,
  label,
  value,
  onChange,
  error,
  storageMessage,
}: {
  name: string;
  label: string;
  value: ImageValue | null;
  onChange: (v: ImageValue | null) => void;
  error?: string;
  storageMessage?: string;
}) {
  const [alt, setAlt] = useState(value?.alt ?? "");
  const [uploading, setUploading] = useState(false);
  const [errors, setErrors] = useState<{ alt?: string; file?: string }>({});
  const fileRef = useRef<HTMLInputElement>(null);

  async function upload() {
    const file = fileRef.current?.files?.[0];
    setErrors({});
    const form = new FormData();
    if (file) form.set("file", file);
    form.set("alt", alt);
    setUploading(true);
    try {
      const res = await fetch("/api/admin/upload", { method: "POST", body: form });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.id) {
        onChange(data as ImageValue);
        if (fileRef.current) fileRef.current.value = "";
      } else {
        setErrors(data.errors ?? { file: "The upload failed. Please try again." });
      }
    } catch {
      setErrors({ file: "The upload failed. Please check your connection and try again." });
    } finally {
      setUploading(false);
    }
  }

  return (
    <fieldset className="flex flex-col gap-3 rounded-[var(--radius)] border border-border p-4" data-image-field={name}>
      <legend className="px-1 text-sm font-medium">{label}</legend>
      {value ? (
        <div className="flex items-start gap-4">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={value.url} alt={value.alt} width={96} height={Math.max(1, Math.round((96 * value.height) / value.width))} className="rounded border border-border" />
          <Button type="button" variant="secondary" size="sm" onClick={() => { onChange(null); setAlt(""); }}>
            <Trash2 size={16} strokeWidth={1.75} aria-hidden="true" />
            Remove image
          </Button>
        </div>
      ) : (
        <p className="flex items-center gap-2 text-sm text-muted">
          <ImageIcon size={16} strokeWidth={1.75} aria-hidden="true" />
          No image yet. The page shows a placeholder.
        </p>
      )}

      <div className="flex flex-col gap-2">
        <Label htmlFor={`${name}-alt`}>Description of the image (required)</Label>
        <Input
          id={`${name}-alt`}
          value={alt}
          maxLength={200}
          onChange={(e) => {
            setAlt(e.target.value);
            if (value) onChange({ ...value, alt: e.target.value });
          }}
          aria-invalid={!!(errors.alt || error)}
          placeholder="For example: A photo of the ring on a bedside table"
        />
        {(errors.alt || error) && (
          <p role="alert" className="text-sm text-danger" data-field-error>
            {errors.alt ?? error}
          </p>
        )}
      </div>

      {storageMessage ? (
        <p role="alert" className="text-sm text-danger" data-testid="storage-message">
          {storageMessage}
        </p>
      ) : (
        <div className="flex flex-col gap-2">
          <Label htmlFor={`${name}-file`}>{value ? "Replace with a new file" : "Choose a file"} (JPEG, PNG or WebP, up to 8 MB)</Label>
          <div className="flex flex-wrap items-center gap-3">
            <input
              ref={fileRef}
              id={`${name}-file`}
              type="file"
              accept="image/jpeg,image/png,image/webp"
              className="max-w-full text-sm"
            />
            <Button type="button" variant="secondary" size="sm" onClick={upload} disabled={uploading}>
              {uploading ? (
                <Loader2 size={16} strokeWidth={1.75} className="animate-spin motion-reduce:animate-none" aria-hidden="true" />
              ) : (
                <Upload size={16} strokeWidth={1.75} aria-hidden="true" />
              )}
              Upload
            </Button>
          </div>
          {errors.file && (
            <p role="alert" className="text-sm text-danger" data-field-error>
              {errors.file}
            </p>
          )}
        </div>
      )}
    </fieldset>
  );
}

