type Errors = Record<string, string>;

function PanelFrame({
  blockId,
  title,
  description,
  visible,
  onVisible,
  build,
  children,
}: {
  blockId: string;
  title: string;
  description?: string;
  visible: boolean;
  onVisible: (v: boolean) => void;
  build: () => { input: Record<string, unknown>; alts?: Record<string, string> };
  children: (errors: Errors) => React.ReactNode;
}) {
  const [result, setResult] = useState<SaveResult | null>(null);
  const [pending, start] = useTransition();
  return (
    <section
      id={`panel-${blockId}`}
      aria-labelledby={`panel-${blockId}-title`}
      className="rounded-[var(--radius)] border border-border bg-surface p-6"
      data-panel={blockId}
    >
      <form
        noValidate
        className="flex flex-col gap-6"
        onSubmit={(e) => {
          e.preventDefault();
          const { input, alts } = build();
          start(async () => {
            setResult(await saveBlockAction(blockId, visible, input, alts ?? {}));
          });
        }}
      >
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h2 id={`panel-${blockId}-title`} className="font-heading text-2xl font-medium">
              {title}
            </h2>
            {description && <p className="mt-1 text-sm text-muted">{description}</p>}
          </div>
          <label className="flex min-h-11 items-center gap-3 text-base">
            <input
              type="checkbox"
              className="size-5 accent-[var(--accent)]"
              checked={visible}
              onChange={(e) => onVisible(e.target.checked)}
              name={`${blockId}-visible`}
            />
            Show on the page
          </label>
        </div>
        {children(result?.errors ?? {})}
        <SaveBar pending={pending} result={result} label={`Save ${title}`} />
      </form>
    </section>
  );
}

function RowTools({
  index,
  count,
  onMove,
  onRemove,
  what,
}: {
  index: number;
  count: number;
  onMove: (from: number, to: number) => void;
  onRemove: (i: number) => void;
  what: string;
}) {
  return (
    <div className="flex items-center gap-1">
      <Button type="button" variant="ghost" size="sm" disabled={index === 0} onClick={() => onMove(index, index - 1)} aria-label={`Move ${what} up`}>
        <ArrowUp size={16} strokeWidth={1.75} aria-hidden="true" />
      </Button>
      <Button type="button" variant="ghost" size="sm" disabled={index === count - 1} onClick={() => onMove(index, index + 1)} aria-label={`Move ${what} down`}>
        <ArrowDown size={16} strokeWidth={1.75} aria-hidden="true" />
      </Button>
      <Button type="button" variant="ghost" size="sm" onClick={() => onRemove(index)} aria-label={`Remove ${what}`}>
        <X size={16} strokeWidth={1.75} aria-hidden="true" />
      </Button>
    </div>
  );
}

function moveItem<T>(list: T[], from: number, to: number): T[] {
  const next = [...list];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
}

function altsOf(...images: (ImageValue | null)[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const i of images) if (i) out[i.id] = i.alt;
  return out;
}

