                  <RowTools index={i} count={items.length} what={`benefit ${i + 1}`} onMove={(a, b) => setItems((l) => moveItem(l, a, b))} onRemove={(idx) => setItems((l) => l.filter((_, n) => n !== idx))} />
                </div>
                <FieldWrap label="Title" htmlFor={`benefit-${i}-title`} error={e[`items.${i}.title`]}>
                  <Input id={`benefit-${i}-title`} value={it.title} onChange={(ev) => update(i, { title: ev.target.value })} aria-invalid={!!e[`items.${i}.title`]} />
                </FieldWrap>
                <FieldWrap label="Text" htmlFor={`benefit-${i}-text`} error={e[`items.${i}.text`]}>
                  <Textarea id={`benefit-${i}-text`} value={it.text} onChange={(ev) => update(i, { text: ev.target.value })} rows={2} />
                </FieldWrap>
                <label className="flex min-h-11 items-center gap-3 text-base">
                  <input type="checkbox" className="size-5 accent-[var(--accent)]" checked={it.hidden} onChange={(ev) => update(i, { hidden: ev.target.checked })} />
                  Hide this benefit
                </label>
              </li>
            ))}
          </ol>
          {e.items && <p role="alert" className="text-sm text-danger" data-field-error>{e.items}</p>}
          <div>
            <Button type="button" variant="secondary" size="sm" disabled={items.length >= 6} onClick={() => setItems((l) => [...l, { title: "", text: "", hidden: false }])}>
              <Plus size={16} strokeWidth={1.75} aria-hidden="true" />
              Add a benefit
            </Button>
          </div>
        </>
      )}
    </PanelFrame>
  );
}

