import { AlertTriangle } from "lucide-react";
import type {
  BenefitsContent,
  FooterContent,
  HeroContent,
  IntegrationsContent,
  PreviewContent,
  WaitlistContent,
} from "@/lib/content";
import { getBlocks, getImagesByIds } from "@/lib/site-data";
import { storageStatus } from "@/lib/storage";
import type { ImageValue } from "@/components/admin/image-field";
import { BenefitsPanel, FooterPanel, HeroPanel, IntegrationsPanel, PreviewPanel, WaitlistPanel } from "./block-panels";

export const dynamic = "force-dynamic";

export default async function PageEditor() {
  const blocks = await getBlocks();
  const get = <T,>(id: string) => {
    const b = blocks.find((x) => x.id === id);
    return b ? { content: b.content as T, visible: b.visible } : null;
  };
  const hero = get<HeroContent>("hero");
  const preview = get<PreviewContent>("preview");
  const integrations = get<IntegrationsContent>("integrations");
  const benefits = get<BenefitsContent>("benefits");
  const waitlist = get<WaitlistContent>("waitlist");
  const footer = get<FooterContent>("footer");

  const images = await getImagesByIds([hero?.content.imageId, hero?.content.backgroundImageId, preview?.content.imageId]);
  const value = (id: string | null | undefined): ImageValue | null => {
    const row = id ? images.get(id) : undefined;
    return row ? { id: row.id, url: row.url, alt: row.alt, width: row.width, height: row.height } : null;
  };
  const status = storageStatus();
  const storageMessage = status.ok ? undefined : status.reason;

  return (
    <div className="flex flex-col gap-8">
      <div>
        <h1 className="heading-section">Page</h1>
        <p className="mt-2 max-w-prose text-muted">
          One panel per block, in the order they appear on the page. Each panel has its own Save button.
        </p>
      </div>
      {waitlist && !waitlist.visible && (
        <p role="alert" className="flex items-start gap-3 rounded-[var(--radius)] bg-danger-soft px-4 py-3 text-danger" data-testid="waitlist-hidden-warning">
          <AlertTriangle size={20} strokeWidth={1.75} className="mt-0.5 shrink-0" aria-hidden="true" />
          The Waitlist block is hidden, so nobody can join. Tick “Show on the page” in the Waitlist panel and save.
        </p>
      )}
      {hero && (
        <HeroPanel
          content={hero.content}
          visible={hero.visible}
          image={value(hero.content.imageId)}
          background={value(hero.content.backgroundImageId)}
          storageMessage={storageMessage}
        />
      )}
      {integrations && <IntegrationsPanel content={integrations.content} visible={integrations.visible} />}
      {preview && (
        <PreviewPanel content={preview.content} visible={preview.visible} image={value(preview.content.imageId)} storageMessage={storageMessage} />
      )}
      {benefits && <BenefitsPanel content={benefits.content} visible={benefits.visible} />}
      {waitlist && <WaitlistPanel content={waitlist.content} visible={waitlist.visible} />}
      {footer && <FooterPanel content={footer.content} visible={footer.visible} />}
    </div>
  );
}

