"use client";

import { useState, useTransition } from "react";
import { ArrowDown, ArrowUp, Plus, X } from "lucide-react";
import { FieldWrap, SaveBar } from "@/components/admin/parts";
import { Button } from "@/components/ui/button";
import { Input, Select, Textarea } from "@/components/ui/input";
import type { WaitlistContent } from "@/lib/content";
import { saveFormAction, type SaveResult } from "../actions";

type Q = { key: string; label: string; type: string; required: boolean; options: string };

export function FormEditor({
  initialFields,
  initialForm,
}: {
  initialFields: Q[];
  initialForm: WaitlistContent["form"];
}) {
  const [fields, setFields] = useState<Q[]>(initialFields);
  const [form, setForm] = useState(initialForm);
  const [result, setResult] = useState<SaveResult | null>(null);
  const [pending, start] = useTransition();
  const errors = result?.errors ?? {};

  const update = (i: number, patch: Partial<Q>) =>
    setFields((l) => l.map((f, n) => (n === i ? { ...f, ...patch } : f)));
  const move = (from: number, to: number) =>
    setFields((l) => {
      const next = [...l];
      const [item] = next.splice(from, 1);
      next.splice(to, 0, item);
      return next;
    });

  return (
    <form
      noValidate
      className="flex flex-col gap-8"
      onSubmit={(e) => {
        e.preventDefault();
        start(async () => {
          setResult(
            await saveFormAction({
              fields: fields.map((f) => ({
                key: f.key,
                label: f.label,
                type: f.type,
                required: f.required,
                options: f.options.split("\n"),
              })),
              form,
            }),
          );
        });
      }}
    >
      <section aria-labelledby="questions-title" className="flex flex-col gap-4 rounded-[var(--radius)] border border-border bg-surface p-6">
        <h2 id="questions-title" className="font-heading text-2xl font-medium">Questions</h2>
        {errors.fields && <p role="alert" className="text-sm text-danger" data-field-error>{errors.fields}</p>}
        <ol className="flex flex-col gap-4">
          {fields.map((f, i) => {
            const isEmail = f.type === "email";
            const choice = f.type === "select" || f.type === "multiselect";
            return (
              <li key={f.key || `new-${i}`} className="flex flex-col gap-4 rounded-[var(--radius)] border border-border p-4" data-question>
                <div className="flex items-center justify-between gap-3">
                  <p className="text-sm font-medium">Question {i + 1}{isEmail && " (email, always required)"}</p>
                  <div className="flex items-center gap-1">
                    <Button type="button" variant="ghost" size="sm" disabled={i === 0} onClick={() => move(i, i - 1)} aria-label={`Move question ${i + 1} up`}>
                      <ArrowUp size={16} strokeWidth={1.75} aria-hidden="true" />
                    </Button>
                    <Button type="button" variant="ghost" size="sm" disabled={i === fields.length - 1} onClick={() => move(i, i + 1)} aria-label={`Move question ${i + 1} down`}>
                      <ArrowDown size={16} strokeWidth={1.75} aria-hidden="true" />
                    </Button>
                    {!isEmail && (
                      <Button type="button" variant="ghost" size="sm" onClick={() => setFields((l) => l.filter((_, n) => n !== i))} aria-label={`Remove question ${i + 1}`}>
                        <X size={16} strokeWidth={1.75} aria-hidden="true" />
                      </Button>
                    )}
                  </div>
                </div>
                <div className="grid gap-4 md:grid-cols-2">
                  <FieldWrap label="Label" htmlFor={`q-${i}-label`} error={errors[`fields.${i}.label`]}>
                    <Input id={`q-${i}-label`} value={f.label} onChange={(e) => update(i, { label: e.target.value })} aria-invalid={!!errors[`fields.${i}.label`]} />
                  </FieldWrap>
                  <FieldWrap label="Type" htmlFor={`q-${i}-type`}>
                    <Select id={`q-${i}-type`} value={f.type} disabled={isEmail} onChange={(e) => update(i, { type: e.target.value })}>
                      {isEmail && <option value="email">Email</option>}
                      <option value="text">Short text</option>
                      <option value="select">Choose one</option>
                      <option value="multiselect">Choose several</option>
                    </Select>
                  </FieldWrap>
                </div>
                {choice && (
                  <FieldWrap label="Options, one per line" htmlFor={`q-${i}-options`} error={errors[`fields.${i}.options`]}>
                    <Textarea id={`q-${i}-options`} rows={4} value={f.options} onChange={(e) => update(i, { options: e.target.value })} aria-invalid={!!errors[`fields.${i}.options`]} />
                  </FieldWrap>
                )}
                <label className="flex min-h-11 items-center gap-3 text-base">
                  <input type="checkbox" className="size-5 accent-[var(--accent)]" checked={isEmail ? true : f.required} disabled={isEmail} onChange={(e) => update(i, { required: e.target.checked })} />
                  Required
                </label>
              </li>
            );
          })}
        </ol>
        <div>
          <Button type="button" variant="secondary" size="sm" disabled={fields.length >= 12} onClick={() => setFields((l) => [...l, { key: "", label: "", type: "text", required: false, options: "" }])}>
            <Plus size={16} strokeWidth={1.75} aria-hidden="true" />
            Add a question
          </Button>
        </div>
      </section>

      <section aria-labelledby="messages-title" className="flex flex-col gap-6 rounded-[var(--radius)] border border-border bg-surface p-6">
        <h2 id="messages-title" className="font-heading text-2xl font-medium">Button and messages</h2>
        <FieldWrap label="Button label" htmlFor="form-submit" error={errors["form.submit_label"]}>
          <Input id="form-submit" value={form.submit_label} onChange={(e) => setForm({ ...form, submit_label: e.target.value })} aria-invalid={!!errors["form.submit_label"]} />
        </FieldWrap>
        <FieldWrap label="Thank-you message" htmlFor="form-success" error={errors["form.success_message"]}>
          <Textarea id="form-success" rows={2} value={form.success_message} onChange={(e) => setForm({ ...form, success_message: e.target.value })} aria-invalid={!!errors["form.success_message"]} />
        </FieldWrap>
        <FieldWrap label="Privacy note" htmlFor="form-privacy" error={errors["form.privacy_note"]} hint="If the settings have a contact email, the page adds a line telling people how to ask to be removed.">
          <Textarea id="form-privacy" rows={2} value={form.privacy_note} onChange={(e) => setForm({ ...form, privacy_note: e.target.value })} />
        </FieldWrap>
      </section>

      <SaveBar pending={pending} result={result} label="Save form" />
    </form>
  );
}

import { getSite } from "@/lib/site-data";
import { SettingsForm } from "./settings-form";

export const dynamic = "force-dynamic";

export default async function SettingsPage() {
  const site = await getSite();
  if (!site) return <p>The site settings are missing. Run the seed script.</p>;
  return (
    <div className="flex flex-col gap-8">
      <div>
        <h1 className="heading-section">Settings</h1>
        <p className="mt-2 max-w-prose text-muted">Site name, tagline, contact email, goal and the start of the goal period.</p>
      </div>
      <SettingsForm
        initial={{
          name: site.name,
          tagline: site.tagline,
          description: site.description,
          contactEmail: site.contactEmail,
          accent: site.accent,
          demoNotice: site.demoNotice,
          successTargetSignups: site.successTargetSignups === null ? "" : String(site.successTargetSignups),
          successTargetDays: site.successTargetDays === null ? "" : String(site.successTargetDays),
          launchedAt: site.launchedAt.toISOString().slice(0, 10),
        }}
      />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { FieldWrap, SaveBar } from "@/components/admin/parts";
import { Input, Textarea } from "@/components/ui/input";
import { saveSettingsAction, type SaveResult } from "../actions";

type Values = {
  name: string;
  tagline: string;
  description: string;
  contactEmail: string;
  accent: string;
  demoNotice: boolean;
  successTargetSignups: string;
  successTargetDays: string;
  launchedAt: string;
};

export function SettingsForm({ initial }: { initial: Values }) {
  const [v, setV] = useState(initial);
  const [result, setResult] = useState<SaveResult | null>(null);
  const [pending, start] = useTransition();
  const e = result?.errors ?? {};
  const set = <K extends keyof Values>(k: K, value: Values[K]) => setV((s) => ({ ...s, [k]: value }));

  return (
    <form
      noValidate
      className="flex flex-col gap-6 rounded-[var(--radius)] border border-border bg-surface p-6"
      onSubmit={(ev) => {
        ev.preventDefault();
        start(async () => setResult(await saveSettingsAction(v)));
      }}
    >
      <div className="grid gap-6 md:grid-cols-2">
        <FieldWrap label="Site name" htmlFor="s-name" error={e.name}>
          <Input id="s-name" value={v.name} onChange={(ev) => set("name", ev.target.value)} aria-invalid={!!e.name} />
        </FieldWrap>
        <FieldWrap label="Tagline" htmlFor="s-tagline" error={e.tagline}>
          <Input id="s-tagline" value={v.tagline} onChange={(ev) => set("tagline", ev.target.value)} />
        </FieldWrap>
      </div>
      <FieldWrap label="Description for search and sharing" htmlFor="s-description" error={e.description}>
        <Textarea id="s-description" rows={3} value={v.description} onChange={(ev) => set("description", ev.target.value)} />
      </FieldWrap>
      <FieldWrap
        label="Contact email (optional)"
        htmlFor="s-contact"
        error={e.contactEmail}
        hint={v.contactEmail.trim() === "" ? "Add a contact email to show a Contact link." : "Shown as the Contact link, and in the privacy note for removal requests."}
      >
        <Input id="s-contact" type="email" value={v.contactEmail} onChange={(ev) => set("contactEmail", ev.target.value)} aria-invalid={!!e.contactEmail} />
      </FieldWrap>
      <FieldWrap label="Accent colour" htmlFor="s-accent" error={e.accent} hint="Used for buttons and highlights. White text must stay readable on it.">
        <div className="flex items-center gap-3">
          <input
            type="color"
            aria-label="Pick the accent colour"
            value={/^#[0-9a-f]{6}$/i.test(v.accent) ? v.accent : "#3f6f73"}
            onChange={(ev) => set("accent", ev.target.value)}
            className="size-11 rounded border border-border bg-surface p-1"
          />
          <Input id="s-accent" value={v.accent} onChange={(ev) => set("accent", ev.target.value)} className="max-w-40" aria-invalid={!!e.accent} />
        </div>
      </FieldWrap>
      <div className="grid gap-6 md:grid-cols-3">
        <FieldWrap label="Goal: number of signups" htmlFor="s-goal" error={e.successTargetSignups} hint="Leave empty for no goal.">
          <Input id="s-goal" inputMode="numeric" value={v.successTargetSignups} onChange={(ev) => set("successTargetSignups", ev.target.value)} aria-invalid={!!e.successTargetSignups} />
        </FieldWrap>
        <FieldWrap label="Goal: number of days" htmlFor="s-days" error={e.successTargetDays}>
          <Input id="s-days" inputMode="numeric" value={v.successTargetDays} onChange={(ev) => set("successTargetDays", ev.target.value)} aria-invalid={!!e.successTargetDays} />
        </FieldWrap>
        <FieldWrap label="Goal period starts" htmlFor="s-launched" error={e.launchedAt}>
          <Input id="s-launched" type="date" value={v.launchedAt} onChange={(ev) => set("launchedAt", ev.target.value)} aria-invalid={!!e.launchedAt} />
        </FieldWrap>
      </div>
      <label className="flex min-h-11 items-center gap-3 text-base">
        <input type="checkbox" className="size-5 accent-[var(--accent)]" checked={v.demoNotice} onChange={(ev) => set("demoNotice", ev.target.checked)} />
        Show a notice at the top that this site is a demonstration
      </label>
      <SaveBar pending={pending} result={result} label="Save settings" />
    </form>
  );
}

