import { defineConfig } from "@playwright/test";

try {
  process.loadEnvFile(".env");
} catch {
  // rely on the real environment
}

const PORT = 3100;

export default defineConfig({
  testDir: "./e2e",
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: [["list"]],
  use: {
    baseURL: `http://localhost:${PORT}`,
    trace: "off",
  },
  // Serves the production build (run `npm run build` first). The test hooks switch is only set here.
  webServer: {
    command: `npx next start -p ${PORT}`,
    url: `http://localhost:${PORT}/robots.txt`,
    reuseExistingServer: false,
    timeout: 60_000,
    env: { ENABLE_TEST_HOOKS: "1", SITE_URL: `http://localhost:${PORT}` },
  },
});

import { expect, type APIRequestContext, type Page } from "@playwright/test";
import { Pool } from "pg";
import { connectionOptions } from "../src/db/connection";

try {
  process.loadEnvFile(".env");
} catch {
  // rely on the real environment
}

export const PASSWORD = "tidewell-dev-password";
export const ADMIN_EMAIL = process.env.ADMIN_EMAIL ?? "rupesh@tidewell.com";
export const E2E_DOMAIN = "@e2e.test";

const pool = new Pool(connectionOptions());

export async function q<T = Record<string, unknown>>(text: string, params: unknown[] = []): Promise<T[]> {
  const res = await pool.query(text, params);
  return res.rows as T[];
}

export function uniqueIp(): string {
  const r = () => Math.floor(Math.random() * 250) + 1;
  return `10.${r()}.${r()}.${r()}`;
}

export function uniqueEmail(tag = "u"): string {
  return `${tag}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}${E2E_DOMAIN}`;
}

export async function useIp(page: Page, ip = uniqueIp()): Promise<string> {
  await page.context().setExtraHTTPHeaders({ "x-forwarded-for": ip });
  return ip;
}

export async function signIn(page: Page, ip = uniqueIp()): Promise<string> {
  await useIp(page, ip);
  await page.goto("/admin/sign-in");
  await page.getByLabel("Email").fill(ADMIN_EMAIL);
  await page.getByLabel("Password").fill(PASSWORD);
  await page.getByRole("button", { name: "Sign in" }).click();
  await page.waitForURL("**/admin");
  return ip;
}

export async function cleanupE2e() {
  await q("delete from signups where email like $1", [`%${E2E_DOMAIN}`]);
}

export async function postSignup(
  request: APIRequestContext,
  body: Record<string, unknown>,
  ip: string,
  headers: Record<string, string> = {},
) {
  return request.post("/api/signup", {
    data: body,
    headers: { "x-forwarded-for": ip, ...headers },
  });
}

export async function signupCount(email: string): Promise<number> {
  const rows = await q<{ n: string }>("select count(*)::int as n from signups where email = $1", [email.toLowerCase().trim()]);
  return Number(rows[0].n);
}

export async function fillAndJoin(page: Page, name: string, email: string) {
  await page.getByLabel("Name", { exact: true }).fill(name);
  await page.getByLabel("Email", { exact: true }).fill(email);
  await page.getByRole("button", { name: "Join the waitlist" }).last().click();
}

export function rgbOf(css: string): [number, number, number] {
  const m = css.match(/rgba?\(([^)]+)\)/);
  if (!m) throw new Error(`Cannot read colour ${css}`);
  const [r, g, b] = m[1].split(/[ ,/]+/).filter(Boolean).map(Number);
  return [r, g, b];
}

export function ratio(a: [number, number, number], b: [number, number, number]): number {
  const lum = ([r, g, b]: [number, number, number]) => {
    const c = (v: number) => {
      const s = v / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * c(r) + 0.7152 * c(g) + 0.0722 * c(b);
  };
  const [hi, lo] = lum(a) > lum(b) ? [lum(a), lum(b)] : [lum(b), lum(a)];
  return (hi + 0.05) / (lo + 0.05);
}

/** A valid 8x6 PNG, made on the fly. */
export function tinyPng(): Buffer {
  // 1x1 transparent PNG scaled by declaring dimensions is not possible, so use a fixed 2x2 image.
  return Buffer.from(
    "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR4nGP8z8Dwn4GBgYGJAQoAHxcCAr7a1ioAAAAASUVORK5CYII=",
    "base64",
  );
}

export { expect };

