import { test, expect, q, ratio, rgbOf, useIp } from "./helpers";

test.beforeEach(async ({ page }) => {
  await useIp(page);
});

test("page-blocks: blocks appear in the brief's order and nothing else of substance", async ({ page }) => {
  await page.goto("/");
  const ids = await page.evaluate(() =>
    [...document.querySelectorAll("main > section, body footer[id]")].map((el) => el.id),
  );
  expect(ids).toEqual(["hero", "integrations", "preview", "benefits", "waitlist", "footer"]);
  await expect(page.getByRole("heading", { level: 1 })).toHaveText("Wake up in the know.");
});

test("navigation: every header and footer link has a real target (W-014, W-015 baseline)", async ({ page }) => {
  await page.goto("/");
  const links = await page.evaluate(() =>
    [...document.querySelectorAll("header a, footer a")].map((a) => ({
      text: (a.textContent ?? "").trim(),
      href: a.getAttribute("href") ?? "",
    })),
  );
  const labels = links.map((l) => l.text);
  for (const label of ["How it works", "Why Tidewell", "Contact", "Join the waitlist"]) expect(labels).toContain(label);
  for (const l of links) {
    expect(l.href, `link ${l.text}`).not.toBe("");
    if (l.href.startsWith("#")) {
      expect(await page.locator(l.href).count(), `anchor ${l.href}`).toBe(1);
    } else {
      expect(l.href).toMatch(/^(mailto:[^@\s]+@[^@\s]+|https?:\/\/)/);
    }
  }
  await page.getByRole("banner").getByRole("link", { name: "Join the waitlist" }).click();
  await expect(page.locator("#waitlist")).toBeInViewport();
});

test("mobile menu opens and closes with the keyboard and traps no focus", async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 667 });
  await page.goto("/");
  const toggle = page.getByRole("button", { name: "Open menu" });
  await toggle.focus();
  await page.keyboard.press("Enter");
  const menu = page.locator("#mobile-menu");
  await expect(menu).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(menu).toBeHidden();
  await expect(page.getByRole("button", { name: "Open menu" })).toBeFocused();
  // Open again and tab through every link: focus leaves the menu, nothing traps it.
  await page.keyboard.press("Space");
  await expect(menu).toBeVisible();
  for (let i = 0; i < 6; i++) await page.keyboard.press("Tab");
  const insideMenu = await page.evaluate(() => !!document.activeElement?.closest("#mobile-menu"));
  expect(insideMenu).toBe(false);
});

test("demo notice is shown because the brief sets demo_notice", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByTestId("demo-notice")).toBeVisible();
});

test("no invented claims, testimonials, counts or ratings (W-029 partial)", async ({ page }) => {
  await page.goto("/");
  const text = (await page.locator("body").innerText()).toLowerCase();
  for (const bad of ["testimonial", "accurately", "battery", "a week", "don't sell", "do not sell", "reviews", "stars", "as seen", "trusted by", "customers"]) {
    expect(text, bad).not.toContain(bad);
  }
  // Digits appear only in the legal year and the demo/other brief text.
  const digits = text.match(/\d+/g) ?? [];
  expect(digits.filter((d) => d !== "2026")).toEqual([]);
});

test("seo basics and crawler files (W-028)", async ({ page, request }) => {
  await page.goto("/");
  expect(await page.locator("html").getAttribute("lang")).toBe("en");
  await expect(page).toHaveTitle(/Tidewell/);
  expect(await page.locator('meta[name="description"]').getAttribute("content")).toContain("smart ring");
  expect(await page.locator('meta[property="og:title"]').getAttribute("content")).toContain("Tidewell");
  expect(await page.locator('meta[property="og:description"]').count()).toBe(1);

  const robots = await (await request.get("/robots.txt")).text();
  expect(robots).toContain("Disallow: /admin");
  expect(robots).toContain("Sitemap:");
  const sitemap = await (await request.get("/sitemap.xml")).text();
  expect(sitemap).toContain("<loc>");

  await page.goto("/admin/sign-in");
  expect(await page.locator('meta[name="robots"]').getAttribute("content")).toContain("noindex");
  const res = await request.get("/admin/sign-in");
  expect(res.headers()["x-robots-tag"]).toContain("noindex");
});

test("unknown path shows a not-found page with a way home", async ({ page }) => {
  const res = await page.goto("/no-such-page");
  expect(res?.status()).toBe(404);
  await page.getByRole("link", { name: "Back to the home page" }).click();
  await expect(page).toHaveURL(/\/$/);
});

for (const [width, height] of [
  [375, 667],
  [1440, 900],
] as const) {
  test(`look: headline and main button visible without scrolling at ${width}x${height}`, async ({ page }) => {
    await page.setViewportSize({ width, height });
    await page.goto("/");
    await expect(page.getByRole("heading", { level: 1 })).toBeInViewport({ ratio: 1 });
    await expect(page.locator("#hero").getByRole("link", { name: "Join the waitlist" })).toBeInViewport({ ratio: 1 });
  });
}

test("look: no horizontal scroll at 375 and 360, rows stack with the art above the text", async ({ page }) => {
  for (const width of [360, 375]) {
    await page.setViewportSize({ width, height: 700 });
    await page.goto("/");
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    expect(overflow).toBeLessThanOrEqual(0);
  }
  const rows = page.locator("[data-benefit-row]");
  expect(await rows.count()).toBe(3);
  for (let i = 0; i < 3; i++) {
    const art = await rows.nth(i).locator("[data-benefit-art]").boundingBox();
    const text = await rows.nth(i).locator("h3").boundingBox();
    expect(art!.y).toBeLessThan(text!.y);
  }
});

test("look: benefit rows alternate sides on desktop and content sits in the 1200px column", async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto("/");
  const rows = page.locator("[data-benefit-row]");
  const sides: boolean[] = [];
  for (let i = 0; i < 3; i++) {
    const art = (await rows.nth(i).locator("[data-benefit-art]").boundingBox())!;
    const text = (await rows.nth(i).locator("h3").boundingBox())!;
    sides.push(art.x < text.x); // true = art on the left
  }
  expect(sides).toEqual([true, false, true]);
  const widths = await page.evaluate(() => [...document.querySelectorAll(".container-page")].map((el) => el.getBoundingClientRect().width));
  expect(widths.length).toBeGreaterThan(4);
  for (const w of widths) expect(w).toBeLessThanOrEqual(1200);
});

test("look: images have alt text and an empty site shows no broken image or empty box", async ({ page }) => {
  await page.goto("/");
  const imgs = await page.evaluate(() =>
    [...document.querySelectorAll("img")].map((i) => ({ alt: i.getAttribute("alt"), ok: i.complete && i.naturalWidth > 0 })),
  );
  for (const i of imgs) {
    expect(i.alt).not.toBeNull();
    expect(i.ok).toBe(true);
  }
  // The placeholders are labelled.
  await expect(page.getByText("Ring photo")).toBeVisible();
  await expect(page.getByText("Concept preview")).toBeVisible();
  const empties = await page.evaluate(() =>
    [...document.querySelectorAll("main section")].filter((s) => (s as HTMLElement).offsetHeight < 40).length,
  );
  expect(empties).toBe(0);
});

test("look: text contrast is at least 4.5:1 for hero text, benefit text and form labels", async ({ page }) => {
  await page.goto("/");
  const measure = async (selector: string) =>
    page.locator(selector).first().evaluate((el) => {
      const color = getComputedStyle(el).color;
      let node: Element | null = el;
      let bg = "rgba(0, 0, 0, 0)";
      while (node) {
        const c = getComputedStyle(node).backgroundColor;
        if (c !== "rgba(0, 0, 0, 0)" && c !== "transparent") {
          bg = c;
          break;
        }
        node = node.parentElement;
      }
      return { color, bg };
    });
  for (const selector of ["#hero h1", "#hero p", "[data-benefit-row] p", "label[for='wl-full_name']", "#waitlist button[type=submit]"]) {
    const { color, bg } = await measure(selector);
    expect(ratio(rgbOf(color), rgbOf(bg)), selector).toBeGreaterThanOrEqual(4.5);
  }
  // Muted text on the page background too.
  const muted = await measure("#preview p");
  expect(ratio(rgbOf(muted.color), rgbOf(muted.bg))).toBeGreaterThanOrEqual(4.5);
});

test("hero background image gets a dimming layer that keeps contrast (W-018 partial)", async ({ page }) => {
  // Use a temporary image row and point the hero background at it with dimming "none".
  const [img] = await q<{ id: string }>(
    "insert into images (url, alt, width, height) values ('/uploads/00000000-0000-0000-0000-000000000000.png', 'Temporary test image', 40, 30) returning id",
  );
  const [row] = await q<{ content: Record<string, unknown> }>("select content from blocks where id='hero'");
  const original = row.content;
  try {
    await q("update blocks set content = $1 where id='hero'", [{ ...original, backgroundImageId: img.id, dimming: "none" }]);
    await page.goto("/");
    const overlay = page.locator("#hero div[aria-hidden='true'].absolute");
    await expect(overlay).toHaveCount(1);
    const bg = await overlay.evaluate((el) => getComputedStyle(el).backgroundColor);
    const alpha = Number(bg.match(/rgba?\([^,]+,[^,]+,[^,]+,\s*([\d.]+)\)/)?.[1] ?? bg.match(/\/\s*([\d.]+)\)/)?.[1] ?? 1);
    expect(alpha).toBeGreaterThanOrEqual(0.55);
    // Worst case: a pure white photo under the overlay, with white text on top.
    const worst = Math.round(255 * (1 - alpha));
    expect(ratio([255, 255, 255], [worst, worst, worst])).toBeGreaterThanOrEqual(4.5);
    const textColor = await page.locator("#hero h1").evaluate((el) => getComputedStyle(el).color);
    expect(rgbOf(textColor)).toEqual([255, 255, 255]);
  } finally {
    await q("update blocks set content = $1 where id='hero'", [original]);
    await q("delete from images where id = $1", [img.id]);
  }
});

import {
  ADMIN_EMAIL,
  E2E_DOMAIN,
  PASSWORD,
  cleanupE2e,
  expect,
  fillAndJoin,
  postSignup,
  q,
  signIn,
  signupCount,
  test,
  uniqueEmail,
  uniqueIp,
  useIp,
} from "./helpers";
import { HP_FIELD } from "../src/lib/honeypot";

void ADMIN_EMAIL;
void PASSWORD;

test.afterAll(async () => {
  await cleanupE2e();
  await q("delete from form_fields where key = 'plan'");
});

test.beforeEach(async ({ page }) => {
  await useIp(page);
});

const EMAIL_MSG = "Please enter a valid email address";

test("W-001: empty or malformed email shows a message under the field, keeps what was typed, stores nothing", async ({ page, request }) => {
  await page.goto("/");
  await page.getByLabel("Name", { exact: true }).fill("Ana Test");
  await page.getByRole("button", { name: "Join the waitlist" }).last().click();
  await expect(page.getByText(EMAIL_MSG)).toBeVisible();
  await page.getByLabel("Email", { exact: true }).fill("not-an-email");
  await page.getByRole("button", { name: "Join the waitlist" }).last().click();
  await expect(page.getByText(EMAIL_MSG)).toBeVisible();
  await expect(page.getByLabel("Name", { exact: true })).toHaveValue("Ana Test");
  await expect(page.getByLabel("Email", { exact: true })).toHaveValue("not-an-email");
  // The server checks it too.
  const res = await postSignup(request, { values: { full_name: "Ana", email: "nope@" } }, uniqueIp());
  expect(res.status()).toBe(400);
  expect((await res.json()).errors.email).toBe(EMAIL_MSG);
  expect(await signupCount("not-an-email")).toBe(0);
});

test("a valid submission through the real page stores one row and replaces the form with the thank-you", async ({ page }) => {
  const email = uniqueEmail("real");
  await page.goto("/");
  let navigations = 0;
  page.on("framenavigated", () => navigations++);
  const before = navigations;
  await fillAndJoin(page, "Real Visitor", email);
  await expect(page.getByTestId("thank-you")).toContainText("Thanks, you're in. We'll be in touch when early access opens.");
  await expect(page.getByTestId("waitlist-form")).toHaveCount(0);
  expect(navigations).toBe(before); // no reload
  const rows = await q<{ email: string; answers: Record<string, string>; source: string; is_sample: boolean }>(
    "select email, answers, source, is_sample from signups where email = $1",
    [email],
  );
  expect(rows).toHaveLength(1);
  expect(rows[0].answers).toEqual({ full_name: "Real Visitor" });
  expect(rows[0].source).toBe("direct");
  expect(rows[0].is_sample).toBe(false);
  // A reload shows the form again.
  await page.reload();
  await expect(page.getByTestId("waitlist-form")).toBeVisible();
});

test("W-002: the same email twice gives the same thank-you and one signup", async ({ page, request }) => {
  const email = uniqueEmail("dup");
  const ip = uniqueIp();
  const a = await postSignup(request, { values: { full_name: "First", email } }, ip);
  const b = await postSignup(request, { values: { full_name: "Second", email: `  ${email.toUpperCase()} ` } }, ip);
  expect(a.status()).toBe(200);
  expect(b.status()).toBe(200);
  expect(await b.json()).toEqual(await a.json());
  expect(await signupCount(email)).toBe(1);
  const [row] = await q<{ answers: Record<string, string> }>("select answers from signups where email = $1", [email]);
  expect(row.answers.full_name).toBe("First"); // a repeat updates nothing
  await page.goto("/");
  await fillAndJoin(page, "Third", email);
  await expect(page.getByTestId("thank-you")).toBeVisible();
  expect(await signupCount(email)).toBe(1);
});

test("W-003: a required question left blank names the question and stores nothing", async ({ page, request }) => {
  const email = uniqueEmail("blank");
  await page.goto("/");
  await page.getByLabel("Email", { exact: true }).fill(email);
  await page.getByRole("button", { name: "Join the waitlist" }).last().click();
  await expect(page.getByText("Please answer “Name”")).toBeVisible();
  const res = await postSignup(request, { values: { email } }, uniqueIp());
  expect(res.status()).toBe(400);
  expect((await res.json()).errors.full_name).toContain("Name");
  expect(await signupCount(email)).toBe(0);
});

test("W-004: a select value that is not one of the options is refused with a generic message", async ({ request }) => {
  await q(
    "insert into form_fields (key, label, type, required, options, position) values ('plan','Plan','select',false,$1,5) on conflict do nothing",
    [JSON.stringify(["Free", "Pro"])],
  );
  try {
    const email = uniqueEmail("tamper");
    const ip = uniqueIp();
    const bad = await postSignup(request, { values: { full_name: "T", email, plan: "Enterprise" } }, ip);
    expect(bad.status()).toBe(400);
    expect((await bad.json()).message).toBe("Please check your answers.");
    expect(await signupCount(email)).toBe(0);
    const good = await postSignup(request, { values: { full_name: "T", email, plan: "Pro" } }, ip);
    expect(good.status()).toBe(200);
    const [row] = await q<{ answers: Record<string, string> }>("select answers from signups where email=$1", [email]);
    expect(row.answers.plan).toBe("Pro");
  } finally {
    await q("delete from form_fields where key = 'plan'");
  }
});

test("W-005: a very long value is refused; HTML is stored and shown as plain text", async ({ page, request }) => {
  const ip = uniqueIp();
  const long = await postSignup(request, { values: { full_name: "x".repeat(400), email: uniqueEmail("long") } }, ip);
  expect(long.status()).toBe(400);
  expect((await long.json()).errors.full_name).toContain("too long");

  const email = uniqueEmail("html");
  const html = `<script>window.__pwned=1</script><b>bold</b>`;
  await page.goto("/");
  await fillAndJoin(page, html, email);
  await expect(page.getByTestId("thank-you")).toBeVisible();
  const [row] = await q<{ answers: Record<string, string> }>("select answers from signups where email=$1", [email]);
  expect(row.answers.full_name).toBe(html);

  await signIn(page);
  await page.goto(`/admin?q=${encodeURIComponent(email)}`);
  const cell = page.locator("[data-signup-row]").first();
  await expect(cell).toContainText(html); // shown literally
  expect(await cell.locator("script, b").count()).toBe(0);
  expect(await page.evaluate(() => (window as unknown as { __pwned?: number }).__pwned)).toBeUndefined();
});

test("W-006: double-clicking Submit gives one thank-you and one signup", async ({ page }) => {
  const email = uniqueEmail("dbl");
  await page.goto("/");
  await page.getByLabel("Name", { exact: true }).fill("Double Click");
  await page.getByLabel("Email", { exact: true }).fill(email);
  await page.getByRole("button", { name: "Join the waitlist" }).last().dblclick();
  await expect(page.getByTestId("thank-you")).toHaveCount(1);
  expect(await signupCount(email)).toBe(1);
  const count = await q<{ n: number }>("select count(*)::int as n from signups where email=$1", [email]);
