    await expect(page.getByRole("alert")).toContainText("locked for ten minutes");
    await expect(page).toHaveURL(/sign-in/);
    await q("delete from rate_events where key = $1", [ip]);
  });

  test("W-023: admin pages redirect to sign-in and owner APIs answer 401 without a session", async ({ page, request }) => {
    for (const path of ["/admin", "/admin/page", "/admin/form", "/admin/settings"]) {
      await page.goto(path);
