import { spawn } from "node:child_process";
import { ADMIN_EMAIL, PASSWORD, expect, test, uniqueIp } from "./helpers";
import { envProblemMessage, missingEnv } from "../src/lib/env";
import { hashPassword, verifyPassword } from "../src/lib/password";

test("W-031 (partial): missing settings are named in a readable message", async () => {
  expect(missingEnv({ DATABASE_URL: "x", ADMIN_EMAIL: "a", ADMIN_PASSWORD_HASH: "h", SESSION_SECRET: "s".repeat(20) })).toEqual([]);
  const msg = envProblemMessage({ DATABASE_URL: "", ADMIN_EMAIL: "a@b.c", SESSION_SECRET: "s".repeat(20) });
  expect(msg).toContain("DATABASE_URL");
  expect(msg).toContain("ADMIN_PASSWORD_HASH");
  expect(msg).not.toContain("SESSION_SECRET");
});

test("W-031: a real server refuses to start without owner credentials and names the setting", async () => {
  const child = spawn("npx", ["next", "start", "-p", "3198"], {
    env: { ...process.env, ADMIN_PASSWORD_HASH: "" },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let output = "";
  child.stdout.on("data", (d) => (output += d));
  child.stderr.on("data", (d) => (output += d));
  const exited = await new Promise<boolean>((resolve) => {
    const timer = setTimeout(() => resolve(false), 40_000);
    child.on("exit", () => {
      clearTimeout(timer);
      resolve(true);
    });
    const poll = setInterval(() => {
      if (output.includes("ADMIN_PASSWORD_HASH")) {
        clearInterval(poll);
        setTimeout(() => resolve(true), 1500);
      }
    }, 200);
  });
  child.kill();
  expect(output).toContain("missing setting ADMIN_PASSWORD_HASH");
  expect(exited).toBe(true);
});

test("hash-password format works with the sign-in check", async () => {
  const hash = hashPassword("pässword 1");
  expect(hash).toMatch(/^scrypt:[0-9a-f]+:[0-9a-f]+$/);
  expect(verifyPassword("pässword 1", hash)).toBe(true);
  expect(verifyPassword("other", hash)).toBe(false);
  expect(verifyPassword("x", "garbage")).toBe(false);
});

test("W-032: a deployed site without an image store token tells the owner uploads are not possible", async ({ page }) => {
  const port = 3199;
  const child = spawn("npx", ["next", "start", "-p", String(port)], {
    env: { ...process.env, VERCEL: "1", BLOB_READ_WRITE_TOKEN: "", ENABLE_TEST_HOOKS: "" },
    stdio: "ignore",
  });
  try {
    const base = `http://localhost:${port}`;
    for (let i = 0; i < 60; i++) {
      try {
        if ((await fetch(`${base}/robots.txt`)).ok) break;
      } catch {
        // not up yet
      }
      await new Promise((r) => setTimeout(r, 500));
    }
    const ip = uniqueIp();
    await page.context().setExtraHTTPHeaders({ "x-forwarded-for": ip });
    await page.goto(`${base}/admin/sign-in`);
    await page.getByLabel("Email").fill(ADMIN_EMAIL);
    await page.getByLabel("Password").fill(PASSWORD);
    await page.getByRole("button", { name: "Sign in" }).click();
    await page.waitForURL("**/admin");
    await page.goto(`${base}/admin/page`);
    await expect(page.getByTestId("storage-message").first()).toContainText("Images cannot be uploaded yet");
    const res = await page.request.post(`${base}/api/admin/upload`, { multipart: { alt: "x" } });
    expect(res.status()).toBe(503);
  } finally {
    child.kill();
  }
});

