export async function register() {
  if (process.env.NEXT_RUNTIME !== "nodejs") return;
  const { envProblemMessage } = await import("./lib/env");
  const problem = envProblemMessage(process.env);
  if (problem) {
    // Refuse to start: a half-working site that answers every request with an error is worse.
    console.error(`\n${problem}\n`);
    process.exit(1);
  }
}

