export function Hero({
  content,
  image,
  background,
  demoNotice,
  hasWaitlist,
}: {
  content: HeroContent;
  image: ImageRow | null;
  background: ImageRow | null;
  demoNotice: boolean;
  hasWaitlist: boolean;
}) {
  // With a background photo the text sits on a dimming layer. "none" is raised to "soft"
  // so text always keeps a contrast of 4.5:1 or more.
  const hasBg = !!background && background.alt.trim() !== "";
  const overlay = content.dimming === "strong" ? "bg-black/70" : "bg-black/55";
  const shownImage = image && image.alt.trim() !== "" ? image : null;

  return (
    <section
      id="hero"
      aria-labelledby="hero-heading"
      className={cn("relative isolate flex items-center overflow-hidden", !hasBg && "hero-plain")}
      style={{
        // Full screen: the header floats on top of the hero, so only the demo notice bar is subtracted.
        minHeight: `calc(100svh${demoNotice ? " - var(--notice-h)" : ""})`,
        paddingTop: "var(--header-h)",
      }}
    >
      {hasBg && background && (
        <>
          <Image
            src={background.url}
            alt=""
            fill
            priority
            sizes="100vw"
            className="-z-20 object-cover"
          />
          <div className={cn("absolute inset-0 -z-10", overlay)} aria-hidden="true" />
