@import "tailwindcss";

/* Colour roles live here and only here. Components use the roles, never raw hex values. */
:root {
  --background: #faf7f2;
  --surface: #ffffff;
  --border: #e7e0d6;
  --foreground: #1c1917;
  --muted: #6b635a;
  --accent: #3f6f73;
  --accent-foreground: #ffffff;
  --accent-soft: color-mix(in srgb, var(--accent) 10%, var(--surface));
  --danger: #b42318;
  --danger-soft: #fef3f2;
  --success: #1a6b3c;
  --success-soft: #edf8f1;
  --radius: 12px;
  --notice-h: 40px;
  --header-h: 72px;
}

@theme inline {
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-border: var(--border);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent-soft: var(--accent-soft);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --color-success: var(--success);
  --color-success-soft: var(--success-soft);
  --font-sans: var(--font-dm-sans), ui-sans-serif, system-ui, sans-serif;
  --font-heading: var(--font-fraunces), ui-serif, Georgia, serif;
  --radius-card: var(--radius);
}

.themed {
  --accent-soft: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

html {
  background: var(--background);
  color: var(--foreground);
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: 17px;
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

@media (min-width: 768px) {
  body {
    font-size: 18px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
  .rise {
    animation: rise 0.6s ease-out both;
  }
  @keyframes rise {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* One section rhythm for every block: 56px on a phone, 96px on desktop. */
.section {
  padding-block: 56px;
}
@media (min-width: 768px) {
  .section {
    padding-block: 96px;
  }
}

.container-page {
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding-inline: 20px;
}
@media (min-width: 768px) {
  .container-page {
    padding-inline: 32px;
  }
}

/* Hero with no photo: a background made only with CSS from the accent and the neutrals:
   two soft glows and a faint grid that fades out toward the bottom. */
.hero-plain {
  background:
    linear-gradient(to bottom, transparent 55%, var(--background) 100%),
    linear-gradient(to right, color-mix(in srgb, var(--border) 45%, transparent) 1px, transparent 1px) 0 0 / 48px 48px,
    linear-gradient(to bottom, color-mix(in srgb, var(--border) 45%, transparent) 1px, transparent 1px) 0 0 / 48px 48px,
    radial-gradient(ellipse 70% 80% at 85% 10%, var(--accent-soft), transparent 70%),
    radial-gradient(ellipse 50% 60% at 0% 100%, color-mix(in srgb, var(--accent) 6%, var(--background)), transparent 70%),
    var(--background);
}

.font-heading {
  font-family: var(--font-heading);
}

.heading-hero {
  font-family: var(--font-heading);
